(window.GIM_TS=window.GIM_TS||{})["Zevachim.3"]={"from":72,"a":[["ומשיבים: \u0003התם חד קרא כוליה לגופיה\u0004 \u0005[שם מקרא אחד כולו לגופו]\u0006 לעצם הענין שצריך לשבת בסוכה, \u0003וחד\u0004 \u0005[ו\u0006מקרא \u0005אחד]\u0006 בא ללמד שתהא שם \u0003סככה,\u0004 שיש צורך שיהיה סיכוך לסוכה, ונמצא שנשארו רמזים עבור שלוש דפנות. ולגוף ההלכה, מעירים: \u0003אתאי הלכתא\u0004 \u0005[באה ההלכה\u0006 למשה מסיני\u0005]\u0006 \u0003וגרעתה\u0004 את הדופן ה\u0003שלישית,\u0004 שאינה צריכה להיות דופן שלמה, \u0003ואוקימתה\u0004 \u0005[והעמידה אותה]\u0006 על \u0003טפח\u0004 בלבד.","ומקשים ממקור נוסף: \u0003אלא מעתה,\u0004 שמועיל המקרא ומועילה המסורת, מה שנאמר ביולדת נקבה \u0003\"וטמאה שבעים\u0004 כנדתה\" (ויקרא יב, ה) שהם ארבעה עשר יום, ולפי הכתיב אפשר לקרוא \u0003\"שבעים\"\u0004 ימים, נאמר גם כן: \u0003אהני קרא\u0004 \u0005[הועיל המקרא]\u0006 שטמאה \u0005ארבעה עשר יום,\u0006 \u0003ואהני\u0004 \u0005[ומועילה]\u0006 ה\u0003מסורת\u0004 שטמאה שבעים יום, וכשנחלק את ההפרש ביניהם, שהוא חמשים וששה יום, נמצא ש\u0003ארבעים ותרין\u0004 \u0005[ושנים]\u0006 ימים \u0003בעיא למיתב\u0004 \u0005[צריכה לשבת]\u0006 בטומאה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שאין מתחשבים במסורת, אלא מניחים שאין מדובר בכתוב אלא על שבועות, משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"כנדתה\"\u0004 כלומר, כימי נידתה, והם שבוע ימים.","ועוד בטעמם של בית הלל, שחטאת שנתנה מתנה אחת כיפר, מעירים: \u0003ותנא מייתי לה מהכא\u0004 \u0005[והתנא מביא\u0006 ראיה לדבר \u0005הזה מכאן],\u0006 וכפי ששנינו בברייתא: נאמר בחטאת החיצונה שלוש פעמים: \u0003\"וכפר\u0004 עליו הכהן\" (ויקרא ד, כו) \u0003\"וכפר\"\u0004 (ויקרא ד, לא) \u0003\"וכפר\"\u0004 (ויקרא ד, לה) בשעיר נשיא, בשעירה ובכשבה, ללמד שכיפר גם אם לא נתן שלוש מתוך ארבע מתנות הדם שבחטאת. וצריך כתובים אלה \u0003מפני הדין\u0004 כלומר, מפני שמן הסברה היה אפשר להגיע למסקנה אחרת,","\u0003שיכול\u0004 היית לומר, \u0003והלא דין\u0004 וסברה \u0003הוא: נאמרו דמים למטה\u0004 בשאר קרבנות (כגון עולה ושלמים) הניתנים בחציו התחתון של המזבח, \u0003ונאמרו דמים למעלה\u0004 בחטאת, שדמה ניתן על קרנות המזבח למעלה, \u0003מה מתן דמים האמורים למטה\u0004 אם \u0003נתנן במתנה אחת\u0004 — \u0003כיפר\u0004 בכך, \u0003אף דמים האמורים למעלה שנתנן במתנה\u0004 \u0003אחת\u0004 — \u0003כיפר.\u0004","ואפשר לומר אחרת, \u0003או כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זו,\u0004 ואמור להיפך: \u0003נאמרו דמים בפנים\u0004 (בחטאות הפנימיות) \u0003ונאמרו דמים בחוץ\u0004 (בחטאת חיצונה), \u0003מה דמים האמורים בפנים\u0004 אם \u0003חיסר אחת מן המתנות\u0004 — \u0003לא עשה ולא כלום, אף דמים האמורין בחוץ\u0004 אם \u0003חיסר אחת מן\u0004 \u0003המתנות\u0004 — \u0003לא עשה ולא כלום!\u0004","הואיל ויש לנו שתי אפשרויות סותרות, \u0003נראה למי דומה\u0004 יותר. מצד אחד \u0003דנין חוץ מחוץ\u0004 כלומר, חטאת חיצונה, משאר זבחים שדמם ניתן על המזבח החיצון, \u0003ואין דנין\u0004 חטאת שב\u0003חוץ מ\u0004חטאת ש\u0003בפנים. או\u0004 מצד אחר, \u0003כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זו: דנין חטאת ו\u0004יש בה מתן \u0003ארבע\u0004 \u0003קרנות\u0004 שבחוץ, \u0003מחטאת וארבע קרנות\u0004 שבפנים, \u0003ואל יוכיח\u0004 קרבן הנעשה \u0003ב\u0004\u0003חוץ, שאין\u0004 הוא \u0003חטאת ו\u0004אין בו מתן \u0003ארבע קרנות!\u0004","וכיוון שאין להכריע מצד הסברה, יש ללמוד מריבוי הכתובים — \u0003תלמוד לומר: \"וכפר\" \"וכפר\" \"וכפר\",\u0004 שלוש פעמים בחטאת החיצונה: \u0003\"וכפר\"\u0004 — \u0003אף על פי שלא נתן אלא שלש\u0004 הרי זה כיפר, ויצא ידי חובתו. \u0003\"וכפר\"\u0004 — \u0003אף\u0004 \u0003על פי שלא נתן אלא שתים, \"וכפר\"\u0004 — \u0003אף על פי שלא נתן אלא אחת.\u0004","ושואלים: \u0003והאי מיבעי ליה לגופיה\u0004 \u0005[ו\u0006הרי כתוב \u0005זה נצרך לו לגופו]\u0006 בכל אחת משלוש החטאות, לומר שהיא מכפרת! \u0003אמר רבא: בר אדא מרי אסברה\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את הדבר, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בכל אחת מן החטאות: \u0003\"וכפר... ונסלח\u0004 לו\" (ויקרא ד, לה), והרי \u0003זו היא כפרה זו היא סליחה,\u0004 ואם כן די היה לומר רק \"ונסלח\", ולכן נאמרה לשון \"וכפר\", להדגיש — גם אם לא נתן את כל המתנות. ומקשים: גם אם יש בכך יתור, מנין שמדובר כשחיסר מארבע המתנות?","\u0003אימא\u0004 \u0005[אמור]\u0006 שמכפר רק כשנתן את כל המתנות, אבל רק שינה את מקומן, ודרוש כך: \u0003\"וכפר\"\u0004 — \u0003אף על פי שלא נתן אלא שלש למעלה ואחת\u0004 \u0003למטה, \"וכפר\"\u0004 — \u0003אף על פי שלא נתן אלא שתים למטה ושתים למעלה,\u0004 \u0003\"וכפר\"\u0004 — \u0003אף על פי שלא נתן\u0004 כולו \u0003למעלה אלא\u0004 הכל \u0003למטה!\u0004","\u0003אמר רב אדא בר\u0004 \u0003יצחק: אם כן,\u0004 שכיפר כשנתן הכל למטה, \u0003ביטלת תורת ארבע קרנות\u0004 הכתובות בחטאת, שהן בראש המזבח. ותוהים: מה טענה היא זו? \u0003ואי רחמנא אמר\u0004 \u0005[ואם התורה אמרה]\u0006 דבר זה \u0005—\u0006 \u0003ליבטלון\u0004 \u0005[שייבטלו]!\u0006","\u0003אמר רבא\u0004 טעם אחר: לפי ש\u0003איזהו דבר שצריך שלש\u0004 לשונות של \"וכפר\" — \u0003הוי אומר: אלו קרנות,\u0004 שצריך ללמד על שלוש מהן שאם לא נתן עליהן כיפר. אבל להכשיר כל ארבע מתנות למטה צריך היה ארבעה \"וכפר\".","ומקשים עוד: ומכל מקום, ניתן היה לדרוש את שלושת הכתובים לגבי מקום המתנות, בלא לבטל תורת ארבע קרנות, ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך: \"וכפר\" — אף על פי שלא נתן אלא שלוש למעלה ואחת למטה, \"וכפר\" — אף על פי שלא נתן אלא שתים למטה ושתים למעלה, \u0003\"וכפר\"\u0004 — \u0003אף על פי שלא נתן אלא אחת למעלה ושלש\u0004 \u0003למטה!\u0004","ומשיבים: הצעה זו מתחילה אין לה מקום, כי \u0003לא מצינו\u0004 (מצאנו) \u0003דמים שחציין\u0004 נותנים \u0003למעלה וחציין למטה.\u0004 ותוהים: \u0003ו\u0004האם \u0003לא\u0004 מצאנו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 לגבי הזאות שמזה הכהן הגדול ביום הכיפורים על הכפורת: \u0003הזה ממנו אחת למעלה ושבע למטה!\u0004","ומשיבים: לא היה מזה ממש למעלה ולמטה, אלא \u0003כמצליף.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כמצליף\"? מחוי\u0004 \u0005[היה מראה]\u0006 \u0003רב יהודה\u0004 בידו — \u0003כמנגדנא\u0004 \u0005[כמי שמכה]\u0006 שמכה בכל פעם במקום נמוך יותר, אבל בסמוך. ומקשים עוד: וכי אין דמים שחציים ניתנים למעלה וחציים למטה?","והרי שנינו כי לאחר שהיזה הכהן הגדול ביום הכיפורים על ארבע קרנות מזבח הזהב, \u0003הזה על טהרו של מזבח שבע פעמים;\u0004"],["\u0003מאי לאו אפלגיה\u0004 \u0005[האם אין\u0006 הכוונה שהיזה \u0005על חציו],\u0006 אמצע גובהו של ה\u0003מזבח, כדאמרי אינשי\u0004 \u0005[כמו שאומרים בני אדם]:\u0006 \u0003טהר טיהרא דיומא\u0004 \u0005[צהרו צהרי היום]\u0006 כלומר, אמצע היום? ונמצא שיש דמים במזבח הפנימי למעלה — על הקרנות שבראשו, ולמטה — על צידו! \u0003אמר רבא בר שילא: לא,\u0004 הכוונה שהיה מזה \u0003אגילוייה\u0004 \u0005[על\u0006 המקום \u0005הגלוי\u0006 בראש המזבח\u0005],\u0006 שהיה מנקה אותו מן הדשן של הקטורת. וזהו ענין \"טהרו\", \u0003כפי\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכעצם השמים לטהר\"\u0004 (שמות כד, י).","ומקשים: ועדיין, האם לא מצאנו דמים שחציים למעלה וחציים למטה? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003שירים,\u0004 ששופכים אותם ליסוד המזבח, גם בקרבן חטאת שדמו ניתן למעלה! ומשיבים: \u0003שירים לא מעכבי\u0004 \u0005[אינם מעכבים]\u0006 את הכפרה, אבל דמים מעכבים אינם ניתנים חציים למעלה וחציים למטה.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003שירים הפנימים\u0004 כלומר, שיריים של הקרבנות שמזים מדמם על קרנות המזבח הפנימי, ששופכים אותם ליסוד המזבח (החיצון), \u0003דאיכא דמאן דאמר מעכבי\u0004 \u0005[שיש מי שאומר\u0006 שהם \u0005מעכבים]!\u0006 ומשיבים: מה שנאמר שאין דמים ניתנים חציים למעלה וחציים למטה, \u0003בחד מקום קאמרינן\u0004 \u0005[במקום אחד אנו אומרים],\u0006 ואילו שיריים של הקרבנות הפנימיים אינם ניתנים בפנים, אלא במזבח החיצון.","שנינו במשנה כי לדעת בית שמאי, אם נתן שתי מתנות בחטאת — כיפר, ובשאר זבחים — מתנה אחת, ולדעת בית הלל גם בחטאת מתנה אחת מכפרת. ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר, בית שמאי אומרים: שתי מתנות שבחטאת\u0004 כלומר, אם היזה שתי הזאות בלבד, \u0003ו\u0004כן מתנה \u0003אחת שבכל\u0004 שאר \u0003הזבחים,\u0004 הואיל והן מכפרות (בדיעבד) — הן \u0003מתרת\u0004 את הזבח באכילה, למרות שלא היזה על כל קרנות המזבח, \u0003ו\u0004הן גם \u0003מפגלות\u0004 שאם חישב באותן שתי מתנות החטאת מחשבת חוץ לזמנו, או באחת משאר הקרבנות — הרי זה עושה את הקרבן פיגול\u0003.\u0004","\u0003בית הלל אומרים: אחת שבחטאת ואחת שבכל הזבחים\u0004 — \u0003מתרת ומפגלת.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אושעיא: אם כן, ליתנייה\u0004 \u0005[שישנה]\u0006 את ההלכה הזו ל\u0003גבי\u0004 \u0005[אצל]\u0006 שאר המקרים שיש בהם \u0003קולי בית שמאי וחומרי בית הלל\u0004 שהוזכרו במסכת עדיות, כי לדעת בית הלל הפיגול בחטאת חל גם אם חישב במתנה אחת מחשבת חוץ לזמנו, ולדעת בית שמאי דווקא כשחישב בשתים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: כי\u0004 \u0003איתשיל\u0004 \u0005[כאשר נשאל\u0006 הדבר\u0005]\u0006 ונחלקו בו, \u0003להתירא איתשיל\u0004 \u0005[ל\u0006גבי \u0005היתר נשאל]\u0006 כלומר, לא לענין הפיגול, אלא לגבי ההיתר לכהנים לאכול את הבשר, \u0003דהוו להו\u0004 \u0005[שהריהם\u0006 נמצאים\u0005]\u0006 \u0003בית שמאי\u0004 סבורים \u0003לחומרא,\u0004 שאינם מתירים את הבשר באכילה אלא לאחר שתי מתנות, ומשום כך לא נשנה הדבר כקולי בית שמאי.","\u0003אמר ר' יוחנן: שלש מתנות\u0004 אחרונות \u0003שבחטאות\u0004 למרות שאינן מעכבות את הכפרה (לדעת בית הלל, שהלכה כמותם), מכל מקום \u0003אינן באות בלילה,\u0004 מאחר והדם נפסל בשקיעת החמה. \u0003ו\u0004הן \u0003באות לאחר מיתה\u0004 אם מתו הבעלים לאחר מתנה אחת, שהרי כבר נתכפרו בראשונה. \u0003ו\u0004כיון שמצוה ליתנן על המזבח, \u0003המעלה מהן בחוץ\u0004 מחוץ למקדש — \u0003חייב.\u0004","\u0003אמר\u0004 \u0003רב פפא: יש מהן\u0004 בשלוש מתנות אלה, דברים שדנים אותן \u0003כתחלתו\u0004 כלומר כדם חטאת לכל דבר, \u0003ויש מהן\u0004 שדנים אותן \u0003כסופו,\u0004 כשיירי הדם.","והוא הולך ומפרט: לגבי החיוב אם נזרק הדם ב\u0003חוץ, ו\u0004לגבי האיסור לזרוק ב\u0003לילה,\u0004 לגבי איסור \u0003זרות\u0004 שזר שזרק את הדם בפנים חייב מיתה, \u0003ו\u0004לענין הצורך לעשות זאת ב\u0003כלי שרת,\u0004 וכן להזות על \u0003קרן\u0004 המזבח דווקא, \u0003ו\u0004שצריך לעשות את ההזיה ב\u0003אצבע,\u0004 וכן לענין \u0003כיבוס\u0004 דם חטאת שניתז על הבגד, \u0003ו\u0004לענין הצורך לשפוך את ה\u0003שירים\u0004 של מתנות אלה על יסוד המזבח — הרי זה \u0003כתחלתן\u0004 כהזאה ראשונה.","אבל אין הדין כן לענין ה\u0003מיתה,\u0004 שיכול להזות דם מתנות אלה לאחר שמתו הבעלים, וכן נתינת דם זה \u0003לא שריא ולא מפגלא\u0004 \u0005[אינה מתרת\u0006 את הבשר באכילה, שכבר הותר בראשונה, \u0005ואינה מפגלת\u0006 אם חישב מחשבת חוץ לזמנו\u0005],\u0006 \u0003ו\u0004כן \u0003לא עיילא לגואי\u0004 \u0005[אינה נכנסת לפנים]\u0006 שאם נכנס דמן של מתנות אלה להיכל — אינו פוסל את החטאת, שלדברים אלה דנים אותן \u0003כסופן\u0004 כאילו היו שיירי דם חטאת.","ולגבי דין כיבוס שיש במתנות אלה, \u0003אמר רב פפא: מנא אמינא\u0004 \u0003לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את ההלכה הזו? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 להלן: אף שדם חטאת שניתז על הבגד טעון כיבוס, אם \u0003ניתז\u0004 דם החטאת ישירות \u0003מן\u0004 \u0003הצואר\u0004 של הבהמה \u0003על הבגד\u0004 — \u0003אינו טעון כיבוס,\u0004 לפי שלא נתקבל הדם בכלי. וכן אם ניתז \u0003מן הקרן\u0004 לאחר שהוזה עליה הדם, \u0003ומן היסוד\u0004 לאחר שנשפכו עליו השיריים — \u0003אינו טעון כיבוס.\u0004 ונדייק: ניתז מן הקרן אינו טעון כיבוס, \u0003הא\u0004 \u0005[אבל]\u0006 אם ניתז \u0003מן\u0004 הדם \u0003הראוי לקרן\u0004 — \u0003טעון כיבוס,\u0004 ושלוש מתנות אלה הרי צריכות להינתן על הקרן.","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 יכול אתה גם לדייק ממה ששנינו: ניתז \u0003מן היסוד אינו טעון\u0004 \u0003כיבוס,\u0004 \u0003הא\u0004 \u0005[אבל]\u0006 ניתז \u0003מן\u0004 הדם \u0003הראוי ליסוד\u0004 כלומר, לאחר שניתן מן הדם על הקרנות, \u0003טעון כיבוס?\u0004 והרי \u0003\"אשר יזה\u0004 דמה על הבגד\" (ויקרא ו, כ) \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003פרט לזה שכבר הוזה!\u0004","אלא \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' נחמיה היא, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' נחמיה אומר:\u0004 \u0003שירי הדם שהקריבן בחוץ\u0004 — \u0003חייב,\u0004 ולדעתו אף שיירי דם החטאת הריהם כדם החטאת עצמו, וממילא גם טעונים כיבוס. אבל לדעת חכמים שאינם סבורים כמוהו, לא ניתן לדייק באופן זה מן המשנה.","ומקשים: וגם לשיטת ר' נחמיה, האם ניתן לדייק כן? \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' נחמיה\u0004 אומר דבר זה \u0003לענין העלאה\u0004 בחוץ, \u0003מידי דהוי\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003איברים ופדרים,\u0004 שאף שאינם מעכבים את הכפרה, מכל מקום אם מעלה אותם בחוץ חייב. אבל \u0003לענין כיבוס מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שמחייב בדם השיריים? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שמענו אותו גם בענין זה."],["\u0003והתניא\u0004 \u0005[והרי\u0006 כך \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003דמים הטעונין יסוד\u0004 ובפשטות הכוונה לשיירי הדם, שטעונים שפיכה ליסוד המזבח — \u0003טעונין כיבוס,\u0004 \u0003ומחשבה\u0004 מחשבת פסול \u0003מועלת\u0004 (מועילה, פועלת) \u0003בהן\u0004 כגון שאם כששופכם מחשב לאכול מן הבשר לאחר הזמן — הרי זה פיגול, \u0003והמעלה מהן בחוץ\u0004 — \u0003חייב. ו\u0004אילו","\u0003דמים\u0004 \u0003הנשפכין לאמה\u0004 (תעלת הניקוז שבמקדש) שהם דמים שנפסלו — \u0003אין טעונין כיבוס, ואין מחשבה מועלת בהן,\u0004 \u0003והמעלה מהן בחוץ\u0004 — \u0003פטור.\u0004","ונברר: \u0003מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה דאמר\u0004 \u0005[אותו שאומר]:\u0006 \u0003מעלה מהן\u0004 מן השיריים \u0003בחוץ חייב? ר' נחמיה היא, וקאמר\u0004 \u0005[והוא אומר]\u0006 שם באותה ברייתא שדם זה \u0003טעון כיבוס.\u0004","ותוהים: \u0003ו\u0004כי \u0003מחשבה מועלת בהן\u0004 בשיירי הדם? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 לענין מחשבת פיגול: דווקא עבודה שמעכבת כפרה יש בה דין זה, \u0003יצאו\u0004 שפיכת \u0003שירים והקטרת אימורין שאין מעכבין את\u0004 \u0003הכפרה, ש\u0004גם \u0003אין מחשבה מועלת בהן!\u0004","אלא, \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שדמים הטעונים יסוד טעונים כיבוס, אינה מדברת בשיריים ממש, לאחר שנשלמה זריקת הדם, אלא \u0003ב\u0004דם שצריך לתת ממנו \u0003שלש מתנות\u0004 האחרונות \u0003שבחטאת.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מדוע קורא להם דמים \u0003טעונין יסוד?\u0004 הרי \u0003לקרן\u0004 המזבח \u0003אזלי\u0004 \u0005[\u0006הם \u0005הולכים]\u0006 ולא ליסוד! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 דמים ה\u0003ניטענין יסוד\u0004 כלומר, שלאחר שיינתנו, יהיו טעונים יסוד. ושואלים: \u0003ומחשבה מועלת בהן? האמרת\u0004 \u0005[הרי אמרת]\u0006 לענין נתינת שלוש מתנות שבחטאת: \u0003לא שריא ולא מפגלא ולא עיילא לגואי\u0004 \u0005[אינה מתרת, ואינה מפגלת\u0006 במחשבת חוץ לזמנו, \u0005ואין\u0006 בה דין \u0005נכנסת לפנים]\u0006 \u0003כסופן\u0004 כלומר, כדין שיריים!","\u0003אלא,\u0004 כך צריך לומר: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 לגבי דמים הטעונים יסוד, שטעונים כיבוס ומחשבה מועלת בהם והמעלה מהם בחוץ חייב, אמנם מדובר בשיריים, אבל לא בשיריים של חטאת רגילה, אלא \u0003ב\u0004שיריים של \u0003דמים הפנימים\u0004 שניתנים על מזבח הזהב בהיכל.","ומקשים: \u0003אבל ב\u0004שיריים של \u0003דמים החיצונים מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003פטור\u0004 אם זרק אותם בחוץ? \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 באותה ברייתא מה דינם של \u0003דמים הנשפכין לאמה, ליפלוג\u0004 \u0003וליתני בדידה\u0004 \u0005[שיחלק וישנה בה עצמה]\u0006 בשיריים \u0003כשרים:\u0004 \u0003במה דברים אמורים? ב\u0004שיריים של \u0003דמים הפנימים, אבל ב\u0004שיריים של \u0003דמים החיצונים\u0004 — \u0003פטור!\u0004","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' נחמיה היא,\u0004 ש\u0003אמר: שירי הדם\u0004 של דמים החיצונים \u0003שהקריבן בחוץ\u0004 \u0003חייב. ו\u0004אם היה משווה שיריים של דמים חיצונים לשיריים של דמים הפנימיים \u0003לא מתני ליה תלתא פטורי לבהדי תלתא חיובי\u0004 \u0005[\u0006היה \u0005נשנה לו שלושה\u0006 דברים \u0005של פטור\u0006 בחיצונים, \u0005אל מול שלושה\u0006 דברים \u0005של חיוב\u0006 שבפנימיים\u0005],\u0006 שהרי גם בחיצונים חייב אם הקריבם בחוץ, ולכן העדיף התנא להשוות שיירי הדם הפנימיים לעומת הדם הפסול. ושבים לדברי רב פפא, שדם שלוש מתנות אחרונות בחטאת טעון כיבוס, ולראיה שהביא לדבריו מדיוק לשון המשנה \"ניתז מן הקרן ומן היסוד אינו טעון כיבוס\".","\u0003רבינא אמר:\u0004 כך יש להבין את המשנה לדעת רב פפא: מה שנאמר \u0003\"מן הקרן\"\u0004 כוונתו מן הקרן \u0003ממש,\u0004 דם שניתז מן הקרן, ומכאן יש לדייק כדברי רב פפא: אבל ניתז מן הדם הראוי לקרן (שלוש מתנות) טעון כיבוס. אבל מה שנאמר \"ניתז \u0003מן היסוד\"\u0004 אין כוונתו מן היסוד ממש, אלא \u0003מן\u0004 הדם \u0003הראוי ליסוד\u0004 כלומר, שיירי הדם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב תחליפא בר גזא לרבינא, אימא\u0004 \u0005[אמור]\u0006 ופרש בדרך אחרת: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 הכוונה ש\u0003ראוי הוא,\u0004 וגם \"מן הקרן\" כוונתו ראוי לקרן, כלומר, דם שלוש מתנות, לומר שאינו טעון כיבוס! השיב לו רבינא: \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 כיצד ניתן להעלות סברה זו? \u0003השתא\u0004 \u0005[\u0006הרי\u0005,\u0006 \u0005עכשיו]\u0006 לפי דעתך שדם ה\u0003ראוי לקרן אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003לא\u0004 יהא טעון כיבוס, דם שהוא \u0003ראוי ליסוד מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 הלוא מיותר הדבר! \u0003אלא\u0004 בהכרח צריך \u0003לפרש:\u0004 \u0003\"מן הקרן\"\u0004 כוונתו \u0003מן הקרן ממש\u0004 שכבר הוזה, אבל \u0003\"מן היסוד\"\u0004 כוונתו \u0003מן הראוי ליסוד.\u0004","שנינו במשנתנו: \u0003כל הניתנין על מזבח הפנימי\u0004 ובכללם פר העלם דבר של כהן משיח, פר העלם דבר של ציבור (וכן שעיר בהעלם עבודה זרה), וכן פר ושעיר של יום הכיפורים — אם חיסר אחת מן המתנות לא עשה כלום. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בפרשת החטאות הפנימיות נאמרה בתחילה פרשת פר כהן משיח, ואחר כך פרשת פר העלם דבר של ציבור, ושם נאמר: \"ועשה לפר... כאשר עשה לפר החטאת כן יעשה לו\" (ויקרא ד, כ), ויש לשאול: \u0003\"ועשה... כאשר עשה\" מה בא ללמוד?\u0004 שהרי לכאורה כל המפורש בפר הראשון (פר כהן משיח) נאמר במפורש גם בפר השני.","אלא בא הכתוב \u0003לכפול בהזאתו\u0004 של פר העלם דבר עצמו, כאילו היה הדבר כתוב בו פעמיים, ושנה עליו הכתוב לעכב, \u0003ולמד\u0004 מכאן \u0003שאם חיסר אחת מכל המתנות\u0004 האמורות בו — \u0003לא עשה ולא כלום. אין לי אלא מתן שבע\u0004 הזאות שעל הפרוכת, \u0003ש\u0004שבע הזאות \u0003מעכבות בכל מקום\u0004 כאשר יבואר להלן (זבחים מ,א), \u0003מתן ארבע\u0004 מתנות על מזבח הזהב \u0003מניין\u0004 שהן מעכבות? \u0003תלמוד לומר: \"כן יעשה\",\u0004","\u0003\"לפר\"\u0004 (ויקרא ד, כ) — \u0003זה\u0004 רמז לפר אחר שדרך עבודתו דומה, הוא \u0003פר יום הכפורים,\u0004"],["\u0003\"כאשר עשה לפר\"\u0004 (ויקרא ד, כ), \"לפר\" — \u0003זה פר כהן משיח,\u0004 ללמד שגם כל מתנותיו מעכבות, \u0003\"החטאת\"\u0004 (ויקרא ד, כ) — \u0003אלו שעירי עבודה זרה\u0004 שמביא הציבור על העלם דבר בעבודה זרה, ללמד שדין עשייתם כפר העלם דבר, שנותן מדמו בפנים ובשרו נשרף. \u0003יכול שאני מרבה\u0004 לענין זה \u0003אף שעירי הרגלים ושעירי ראשי חדשים\u0004 שגם הם חטאות של ציבור, שייעשו בפנים, ככל דיני פר העלם דבר של ציבור? \u0003תלמוד לומר:\u0004 \"כן יעשה \u0003לו\"\u0004 (ויקרא ד, כ) למעט: דווקא לו ולא לאחר.","ושואלים: \u0003ומה\u0004 \u0003ראית לרבות את אלו,\u0004 שעירי עבודה זרה, \u0003ולהוציא את אלו,\u0004 שעירי רגלים ושעירי ראשי חדשים? ומשיבים: \u0003אחר שריבה\u0004 \u0003הכתוב ומיעט, מרבה אני את אלו\u0004 (שעירי עבודה זרה) \u0003שמכפרין על עבירת מצוה ידועה\u0004 עבודה זרה, כמו פר העלם דבר, שבא על שגגת הוראה של הסנהדרין לאחר שנודעה להם טעותם, \u0003ומוציא אני אלו\u0004 (שעירי הרגלים וראשי חדשים) \u0003שאין מכפרין על עבירת מצוה ידועה,\u0004 אלא על טומאת מקדש וקדשיו שלא נודעה.","וממשיכה הברייתא בענין פר העלם דבר: \u0003\"וכפר\"\u0004 (ויקרא ד, כ) — לרבות \u0003אף על פי שלא סמך\u0004 כלומר, למרות שלא סמכו הזקנים ידיהם על ראש הפר, \u0003\"ונסלח\"\u0004 — \u0003אף על פי שלא נתן שירים\u0004 ליסוד.","ושואלים: כיון שהפסוק אינו מפרש במה בא הריבוי ובמה המיעוט, \u0003ומה ראית לפסול ב\u0004שבע \u0003הזאות\u0004 ולומר שהן מעכבות מ\"ועשה... כאשר עשה\", \u0003ולהכשיר בסמיכה ושירים\u0004 מ\"וכפר\" ו\"ונסלח\"?","ומשיבים: \u0003אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003פוסל\u0004 אני \u0003ב\u0004שבע \u0003הזאות שמעכבות בכל מקום\u0004 (כאשר יבואר להלן), \u0003ומכשיר אני בסמיכה ושירים שאין מעכבות\u0004 \u0003בכל מקום,\u0004 וסברה היא לומר שלא יעכבו גם כאן."],["ומבארים את הברייתא לפרטיה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אין לי אלא מתן שבע\u0004 שמעכבות זו את זו, מפני \u0003ש\u0004שבע \u0003מעכבות בכל מקום.\u0004 ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 מצינו שהן מעכבות? \u0003אמר רב פפא: בפרה\u0004 אדומה \u0003ובנגעים\u0004 (בטהרת המצורע).","ועוד שנינו בברייתא: \u0003מתן ארבע\u0004 שעל קרנות מזבח \u0003הקטורת\u0004 \u0003מנין? תלמוד לומר: \"כן יעשה\"\u0004 (ויקרא ד, כ). ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מתן שבע\u0004 שהן מעכבות? משום \u0003דכתיבן וכפילן\u0004 \u0005[ש\u0006הן \u0005כתובות וכפולות]\u0006 במלים \"ועשה... כאשר עשה\" ללמד שהן מעכבות, \u0003מתן ארבע נמי כתיבן וכפילן\u0004 \u0005[גם כן כתובות וכפולות]\u0006 ומדוע יהא דינן שונה?","\u0003אמר ר' ירמיה: לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ל\u0004דעת \u0003ר' שמעון\u0004 שאינו סבור שכתובות כאן ארבע מתנות, אלא רק שתים, ושתים נלמדו מהיקש, ויש להן צורך בריבוי מיוחד. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לגבי ההזאות על מזבח הפנימי: \u0003למעלה,\u0004 בפר כהן משיח, הוא \u0003אומר: \"קרן קרנות\"\u0004 (ויקרא ד, ז) כלומר, שיכול היה לכתוב \"קרן\" וכתב \"קרנות\" — הרי \u0003שתים, למטה\u0004 בפר העלם דבר \u0003הוא אומר: \"קרן קרנות\"\u0004 (ויקרא ד, יח) — ביחד הרי \u0003ארבע\u0004 קרנות, \u0003דברי ר' שמעון.\u0004","\u0003ר' יהודה אומר: אינו צריך\u0004 לראיה זו, אלא \u0003הרי הוא אומר\u0004 באותם פסוקים \u0003\"באהל מועד\"\u0004 (ויקרא ד, יח), וביטוי זה מיותר, ובא ללמד שצריך לתת מן הדם \u0003על כל\u0004 קרנות המזבח \u0003האמור באהל מועד.\u0004 ושואלים: \u0003ור' יהודה\u0004 שחולק על ר' שמעון, הכתוב \u0003\"כן יעשה\",\u0004 שר' שמעון דורשו לענין ארבע מתנות, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006","ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005אותו לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003לפי שלא למדנו לפר יום הכפורים לסמיכה\u0004 שלא נאמר בכתוב שצריך הכהן הגדול לסמוך עליו, \u0003ו\u0004כן \u0003שירי הדם\u0004 שלו, לא נזכר בכתוב שצריך לשופכם על יסוד מזבח העולה, \u0003מנין\u0004 שצריכים לעשות כן? \u0003תלמוד לומר: \"כן יעשה\".\u0004","ושואלים: \u0003ולפר יום הכפורים לא למדנו? הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 בדרשה הקודמת: \u0003\"לפר\"\u0004 — \u0003זה\u0004 פר \u0003יום הכפורים,\u0004 שלמדים מפר העלם דבר לפר יום הכיפורים לכל מעשיו!","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005]\u0006 להישנות, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים רק ב\u0003עבודה דמעכבא\u0004 \u0005[שמעכבת]\u0006 את ה\u0003כפרה\u0004 כהזאת הדם, \u0003אבל עבודה דלא מעכבא\u0004 \u0005[שאינה מעכבת]\u0006 \u0003כפרה,\u0004 כסמיכה ושיירי הדם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם אותה צריך לעשות בפר יום הכיפורים.","ושואלים: \u0003ור' שמעון, האי\u0004 \u0005[\u0006הייתור \u0005הזה]\u0006 \u0003\"באהל מועד\"\u0004 ממנו למד ר' יהודה מתן ארבע, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003\"באהל מועד\" מבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר \u0003שאם נפחתה תקרה של היכל לא היה מזה,\u0004 שאין זה עוד \"אהל מועד\". \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יהודה, מהיכן הוא לומד זאת? \u0003מ\u0004מה שנאמר \u0003\"אשר\u0004 באהל מועד\" שהוא מיותר. \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' שמעון? \u0003\"אשר\" לא דריש\u0004 \u0005[אינו דורש]\u0006 כלשון יתור.","\u0003אביי אמר: לר' יהודה נמי איצטריך\u0004 \u0005[גם כן הוצרך]\u0006 הכתוב \"כן יעשה\", ללמד על מתן ארבע שהוא מעכב, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003סמיכה ושירי הדם,\u0004 שלמדנו בברייתא \u0003דאף על גב דכתיבן וכפילן לא מעכבא\u0004 \u0005[שאף על פי ש\u0006הן \u0005כתובות וכפולות אינה מעכבת],\u0006 משום שבדרך כלל אינן מעכבות, הייתי אומר \u0003מתן ארבע נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תתעכב,\u0004 שהרי בחטאת חיצונה אין מעכבת אלא מתנה אחת, כמבואר במשנתנו, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \"כן יעשה\" שהוא מעכב.","שנינו בברייתא: \u0003\"לפר\"\u0004 — \u0003זה פר יום הכפורים.\u0004 ושואלים: \u0003למאי הילכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 נאמרה דרשה זו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לעכב,\u0004 לומר שכל האמור בעבודת יום הכיפורים הוא לעכב — \u0003פשיטא\u0004 \u0005[פשוט],\u0006 הרי \u0003\"חקה\" כתיבה ביה\u0004 \u0005[כתובה בו]\u0006 \"והיתה זאת לכם לחוקת עולם\" (ויקרא טז, לד), ובכל מקום שנאמרה \"חוקה\" הרי הוא לעכב!","\u0003אמר רב נחמן בר יצחק: לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ל\u0004דעת \u0003ר' יהודה,\u0004 ש\u0003אמר: כי כתיבה\u0004 \u0005[כאשר נאמרה]\u0006 \u0003\"חקה\"\u0004 הרי זה רק לגבי \u0003דברים הנעשים בבגדי לבן בפנים\u0004 (בקודש הקדשים, הזאות והכנסת הקטורת), \u0003ש\u0004באלה \u0003אם הקדים\u0004 \u0003מעשה לחבירו לא עשה ולא כלום,\u0004","\u0003אבל דברים הנעשים בבגדי לבן בחוץ\u0004 (בהיכל, על הפרוכת ועל מזבח הזהב), אם \u0003הקדים מעשה לחבירו\u0004 — \u0003מה שעשה עשוי.\u0004 ואם כן \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מ\u0004כיון ש\u0003כסידרן לא מעכבי\u0004 \u0005[אינו מעכב],\u0006 \u0003הזאות\u0004 עצמן \u0003נמי לא מעכבי\u0004 \u0005[גם כן אינן מעכבות],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \"לפר\" האמור כאן שהן מעכבות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ומי מצית אמרת הכי\u0004 \u0005[האם יכול אתה לומר כך]\u0006 שמכאן למד ר' יהודה שההזאות מעכבות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 הפסוק \u0003\"וכלה מכפר את הקדש\"\u0004 (ויקרא טז, כ) האמור בעבודת יום הכיפורים, מיותר לעניינו, והוא בא ללמדנו: \u0003אם כיפר\u0004 הכהן, שעשה את העבודות המכפרות, כלומר, היזה את ההזאות בפנים — \u0003כילה\u0004 את העבודה, אף שלא שפך את שיירי הדם, \u0003ואם לא כיפר\u0004 — \u0003לא כילה, דברי ר' עקיבא.\u0004","\u0003אמר לו ר' יהודה, מפני מה לא נאמר\u0004 אחרת: \u0003אם כילה\u0004 לגבי כל סדר העבודה, ובכלל זה הזאות שבהיכל, ואפילו שפיכת שיירי הדם — \u0003כיפר, ואם לא כילה\u0004 — \u0003לא כיפר?\u0004 הרי שמכאן למד ר' יהודה דין זה!","אלא \u0003אמר רב פפא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 ההשוואה האמורה בפסוק זה לפר יום הכיפורים, \u0003אלא\u0004 ללמוד שלוש הלכות מן האמור בפר כהן משיח \"וטבל הכהן את אצבעו בדם\" (ויקרא ד, ו): \u0003\"את\", דם ובטבילה.\u0004 ומבארים: \u0003\"את\"\u0004 — \u0003אמר רב אחא בר יעקב: לא נצרכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003להכשיר\u0004"],["\u0003אמין\u0004 (שלפוחיות או יבלות) \u0003שבאצבע\u0004 שאינן חוצצות בין האצבע לדם. \u0003\"בדם\"\u0004 (ויקרא ד, ו) — \u0003שיהא בדם\u0004 שבכלי \u0003שיעור טבילה מעיקרא\u0004 \u0005[מתחילה]\u0006 לכל ההזאות, ולא שיוסיף בכל פעם מעט דם לכלי ויזה. וכן נאמר \u0003\"וטבל\u0004 הכהן את אצבעו בדם\" — \u0003ולא\u0004 יהא \u0003מספג\u0004 (מקנח) דם מעל גבי דפנות הכלי, שיהא די דם כדי לטבול בו את האצבע.","ומסבירים: \u0003ואיצטריך למכתב\u0004 \u0005[והיה צריך לכתוב]\u0006 \u0003\"בדם\",\u0004 \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"וטבל\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אף על גב דליכא\u0004 \u0005[אף על פי שאין]\u0006 \u0003שיעור טבילה מעיקרא\u0004 \u0005[מתחילה]\u0006 אלא כדי הזאה אחת, אלא שבכל פעם הוסיף בכלי מדם הפר כדי שיעור טבילה אחת, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"בדם\"\u0004 שדם כל ההזאות נתקבל מתחילה בכלי.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"בדם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 אם היה מתחילה דם כשיעור, אין צורך שיהא בהזאות האחרונות שיעור טבילה, אלא \u0003אפילו מספג,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"וטבל\".\u0004","ועל יתור נוסף באותה פרשה שואלים: מה שנאמר שם \"ונתן הכהן מן הדם על \u0003מזבח קטרת\u0004 ה\u0003סמים\u0004 אשר לפני ה'\" (ויקרא ד, ז) \u0003למה לי\u0004 לכתוב בו \"קטורת הסמים\"? די במה שנאמר בו \"אשר לפני ה'\" ללמדנו באיזה מזבח מדובר! לומר \u0003שאם לא נתחנך המזבח\u0004 מתחילה \u0003בקטורת הסמים\u0004 — \u0003לא היה מזה\u0004 עליו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב פפא,\u0004 שלכך נרמז פר יום הכיפורים בפסוק המיותר שבפר העלם דבר — ל\"את בדם וטבילה\" האמור בפר כהן משיח (שאף הוא נזכר בפסוק). \u0003\"ועשה\u0004 לפר... \u0003כאשר עשה\u0004 לפר\" (ויקרא ד, כ), \u0003מה תלמוד לומר \"לפר\"? לרבות פר\u0004 \u0003יום הכפורים לכל מה שאמור בענין\u0004 בפר כהן משיח, והוא \"את בדם וטבילה\", \u0003דברי רבי.\u0004","\u0003אמר ר' ישמעאל:\u0004 אין צורך לריבוי זה, שהרי \u0003קל וחומר\u0004 הוא! \u0003ומה במקום שלא הושוה קרבן לקרבן\u0004 בקרבנות שאינם ממין אחד של בהמה — \u0003השוה מעשים למעשים\u0004 שכל דרך עשייתם שווה בהזאות הדם, וכאשר יבואר להלן. \u0003מקום שהשוה קרבן לקרבן\u0004 כגון פר כהן משיח ופר יום הכיפורים — \u0003אינו דין שישוה מעשה למעשה?\u0004 ואם כן, אין צורך ללמוד זאת מריבוי הכתוב.","\u0003אלא\u0004 כך צריך לדרוש: \u0003מה תלמוד לומר\u0004 \"ועשה \u0003לפר\"\u0004 — \u0003זה פר העלם דבר של צבור,\u0004 \"כאשר עשה \u0003לפר\"\u0004 — \u0003זה פר כהן משיח.\u0004","ומבארים את הברייתא: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ומה במקום שלא הושוה\u0004 \u0003קרבן לקרבן.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לא הושוה קרבן לקרבן\"?\u0004 לאלו קרבנות הוא מתכוון, שאינם מאותו מין בהמה, אך מעשיהם שווים?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003פר יום הכפורים ושעיר יום הכפורים,\u0004 שזה פר וזה שעיר, ומהם למדים בקל וחומר להשוות מעשיו של פר יום הכיפורים לפר כהן משיח לענין \"את בדם וטבילה\" — \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 את הלימוד, ולטעון: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 פר ושעיר של יום הכיפורים, שיש בהם צד מיוחד של דמיון, \u0003שכן נכנס דמם\u0004 גם \u0003לפניי ולפנים\u0004 אל קודש הקודשים, מה שאין כן בפר העלם דבר, שהזאת דמו רק בהיכל!","\u0003אלא\u0004 תאמר שמדובר ב\u0003פר העלם דבר של צבור ושעירי\u0004 העלם דבר של \u0003עבודה זרה,\u0004 שאף שאינם ממין אחד עבודתם שווה — \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]:\u0006 \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן\u0004 שניהם \u0003מכפרין על עבירות\u0004 \u0003מצוה ידועה,\u0004 ואין להסיק מכאן על פר יום הכיפורים, שבא לכפר על עבירות שאינן ידועות!","\u0003אלא\u0004 צריך לומר שמדבר ב\u0003פר העלם דבר של צבור ושעיר של יום הכפורים. והכי קאמר\u0004 \u0005[וכך אומר]\u0006 ר' ישמעאל: \u0003ומה במקום שלא הושוו קרבן לקרבן, דהאי\u0004 \u0005[שזהו]\u0006 \u0003פר והאי\u0004 \u0005[וזהו]\u0006 \u0003שעיר\u0004 — מכל מקום \u0003הושוו מעשים למעשים למאי דכתב בהו\u0004 \u0005[למה שכתב בהם],\u0006 שלמרות ששעיר יום הכיפורים נעשה גם בקודש הקדשים, מכל מקום בעבודות הנעשות בהיכל המשותפות לשניהם מעשיהם שווים, שצריך להזות באצבע על הפרוכת ועל קרנות המזבח, \u0003מקום שהושוה קרבן לקרבן,\u0004 כגון \u0003דהאי\u0004 \u0005[שזהו]\u0006 \u0003פר והאי\u0004 \u0005[וזהו]\u0006 \u0003פר\u0004 — \u0003אינו דין\u0004"],["\u0003שהושוו מעשים למעשים? ו\u0004לפי קל וחומר זה","\u0003אתא ליה\u0004 \u0005[בא לו,\u0006 נלמד\u0005]\u0006 \u0003פר יום הכפורים ל\u0004למוד לגביו את הדינים שסימנם \u0003\"את בדם וטבילה\" מפר כהן משיח.\u0004 \u0003ו\u0004כן \u0003אתי ליה\u0004 \u0005[בא לו,\u0006 נלמד\u0005]\u0006 \u0003שעיר יום הכפורים משעירי עבודה זרה\u0004 להשוות את מעשיהם לענין \"את בדם וטבילה\", \u0003מקל וחומר\u0004 זה, שהרי הושווה קרבנם, ששניהם שעירים.","ותוהים: וכיצד ילמדו שעירי עבודה זרה על שעיר יום הכיפורים? \u0003וכי דבר הלמד\u0004 שדינו נלמד \u0003בהיקש\u0004 לדבר אחר, \u0003חוזר ומלמד\u0004 על דבר \u0003אחר\u0004 \u0003בקל וחומר\u0004 בדיני קדשים? והרי בשעירי עבודה זרה עצמם לא הוזכרו \"את בדם וטבילה\", ולא למדנו בהם דינים אלו אלא מן ההיקש בפסוק \"ועשה... כאשר עשה\", שם נרמזו גם הם יחד עם פר כהן משיח! \u0003אמר רב פפא:\u0004 כך \u0003קסבר תנא דבי\u0004 \u0005[סבור התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 כי \u0003דבר הלמד בהיקש חוזר ומלמד בקל וחומר.\u0004","וממשיכים בביאור דברי ר' ישמעאל בברייתא שבעמוד הקודם: אלא מה תלמוד לומר \u0003\"לפר\"\u0004 — \u0003זה פר העלם דבר של צבור.\u0004 ותוהים: \u0003הא\u0004 \u0005[הרי]\u0006 פסוק זה \u0003ב\u0004פר העלם דבר של \u0003ציבור גופיה כתיב\u0004 \u0005[עצמו\u0006 הוא \u0005כתוב],\u0006 ומה צורך ללומדו מריבוי הכתוב! \u0003אמר רב פפא: משום דבעי אגמורי\u0004 \u0005[ש\u0006הוא \u0005רוצה ללמוד]\u0006 מ\u0003פר העלם דבר של צבור\u0004 \u0003ב\u0004ענין הקטרה של האימורים, ובכללם \u0003יותרת\u0004 הכבד \u0003ושתי כליות, לשעירי עבודה זרה,\u0004 לומר שגם הם חייבים בכך, למרות שלא נאמר בהם דין זה.","\u0003ופר העלם דבר של צבור\u0004 \u0003בגופיה\u0004 \u0005[בו עצמו]\u0006 \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 דין זה, אלא \u0003בהיקשא אתי\u0004 \u0005[בהיקש\u0006 הוא \u0005בא]\u0006 מפר כהן משיח, שם נאמר דין זה (ויקרא ד, ח—ט), על כן \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לרבות אותו שוב במילה \u0003\"לפר\"\u0004 כדי לחזור ולהקישו לפר כהן משיח פעם נוספת,","\u0003למיהוי כמאן דכתיב ביה\u0004 \u0003בגופיה\u0004 \u0005[שיהיה כאילו כתוב בו בעצמו]\u0006 דין זה, \u0003ו\u0004כך \u0003לא ליהוי\u0004 \u0005[יהיה]\u0006 הלימוד ממנו לשעירי עבודה זרה בגדר \u0003דבר הלמד בהיקש חוזר ומלמד\u0004 שוב \u0003בהיקש,\u0004 שדבר זה אין עושים בקדשים.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא על פסוק זה \u0005כשיטתו]\u0006 של \u0003רב פפא: \"ועשה\u0004 לפר... \u0003כאשר עשה\"\u0004 (ויקרא ד, כ) \u0003מה תלמוד\u0004 (צורך) \u0003לומר\u0004 \"ועשה \u0003לפר\"?\u0004 הרי מדובר בפסוק זה על הפר!","אלא \u0003לפי שנאמר\u0004 בפרשת שעירי עבודה זרה: \u0003\"והם הביאו את קרבנם אשה לה'\u0004 וחטאתם לפני ה' על שגגתם\" (במדבר טו, כה), \u0003\"חטאתם\"\u0004 — \u0003אלו שעירי עבודה זרה\u0004 שבהם מדובר באותה פרשה, \u0003\"שגגתם\"\u0004 — \u0003זה פר העלם דבר של צבור,\u0004 שהוא בא על שגגת הציבור. ובמה שהוזכרו יחד \u0003\"חטאתם על שגגתם\"\u0004 והוקשו זה לזה — \u0003אמרה תורה: חטאתם הרי היא לך כשגגתם,\u0004 שצריך להקטיר את האימורים בשעירי עבודה זרה כדרך שעושה כן בפר העלם דבר.","ויש לשאול: לגבי \u0003שגגתם\u0004 פר העלם דבר \u0003מהיכן למדת\u0004 דין זה? האם \u0003לא בהיקשא\u0004 \u0005[בהיקש]\u0006 מפר כהן משיח? שהרי בפר העלם דבר עצמו לא הוזכרו אימורים אלו. ועל כך יש להקשות: \u0003וכי דבר הלמד בהיקש חוזר ומלמד בהיקש?\u0004","על כן דרש ר' ישמעאל בברייתא: \u0003תלמוד לומר:\u0004 \"ועשה \u0003לפר\"\u0004 (ויקרא ד, כ) — \u0003זה פר העלם דבר של צבור,\u0004 \"כאשר \u0003עשה\u0004 \u0003לפר\"\u0004 (ויקרא ד, כ) — \u0003זה פר כהן משיח,\u0004 להקישם פעם נוספת, כאילו היתה הקטרת אימורים כתובה במפורש בפר העלם דבר, וכך ניתן ללמוד ממנו בהיקש לשעירי עבודה זרה, וכדברי רב פפא.","ומעתה דנים בברייתא זו שהבאנו, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"חטאתם\"\u0004 — \u0003אלו שעירי עבודה זרה,\u0004 והקשנו אותם בפסוק זה לפר העלם דבר. ושואלים: \u0003תיפוק ליה מקרא קמא\u0004 \u0005[יצא,\u0006 ילמד לו \u0005הדבר מהפסוק הראשון]\u0006 האמור בפר העלם דבר: (\"ועשה... כאשר עשה\" ויקרא ד, כ), ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהובאה בתחילת סוגיה זו (לעיל זבחים לט,ב): \u0003\"החטאת\"\u0004 — הרי זה בא \u0003לרבות שעירי עבודה זרה! אמר רב פפא: איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 כי אם היה רק ההיקש הראשון, \u0003סלקא דעתך אמינא\u0004 \u0005[עולה\u0006 היה \u0005על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 להשוות שעירי עבודה זרה לפר העלם דבר, אמורים ב\u0003הזאות, דכתיבן בגופיה\u0004 \u0005[ש\u0006הן \u0005כתובות ב\u0006פר העלם דבר \u0005עצמו],\u0006"],["\u0003אבל יותרת ושתי כליות, דלא כתיבן בגופיה\u0004 \u0005[שאינן כתובות בו עצמו]\u0006 בפר העלם דבר — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יילמדו ממנו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 בהיקש נוסף שגם לענין זה שניהם שווים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא, \"פר\u0004 \u0003יום הכפורים לכל מה שאמר בענין\" קאמר\u0004 \u0005[אומר],\u0006 שלמדים את כל האמור בפר העלם דבר מהיקש אחד! ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 לגבי דרך הדרשה בענין זה, \u0003תנא דבי\u0004 \u0005[התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב מרבי הכי\u0004 \u0005[מרבה כך]\u0006 בהיקש אחד, ואילו \u0003תנא דבי\u0004 \u0005[התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל לא מרבי הכי\u0004 \u0005[אינו מרבה כך],\u0006 וסבור שצריך לימוד נוסף לענין יותרת וכליות.","אגב הדיון בהלכות אלו מביאים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית מדרשו]\u0006 של \u0003ר' ישמעאל: מפני מה נאמרו יותרת ושתי כליות בפר כהן משיח, ולא נאמרו בפר העלם דבר של צבור? משל למלך בשר ודם שזעם על אוהבו\u0004 שחטא כלפיו, \u0003ומיעט בסרחונו\u0004 כלומר מיעט לדבר על קלקלתו \u0003מפני חיבתו.\u0004 וכך עם ישראל הם אהוביו של הקדוש ברוך הוא, ולכן ממעט בפרטים הנוגעים לקרבן חטאתם.","\u0003ו\u0004עוד \u0003תנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מפני מה נאמרה\u0004 \"והזה... את פני \u0003פרכת הקדש\"\u0004 (ויקרא ד, ו) \u0003ב\u0004הזאת דמו של \u0003פר כהן משיח, ולא נאמר בפר העלם דבר של צבור,\u0004 ששם נאמר רק \"והזה את פני הפרוכת\" (ויקרא ד, יז)? \u0003משל למלך בשר ודם שסרחה\u0004 (חטאה) \u0003עליו מדינה, אם מיעוטה סרחה\u0004 — \u0003פמליא שלו מתקיימת,\u0004 הריהו ממשיך לנהוג עם הקרובים אליו כרגיל, אבל \u0003אם רובה\u0004 של המדינה \u0003סרחה\u0004 — \u0003אין פמליא שלו מתקיימת,\u0004 וגם הקרובים אליו אינם נפגשים עמו ממש, כרגיל. וכך כאשר העם כולו חוטא, אין הכהן המזה על הפרוכת נחשב כעומד ממש מול הקודש.","שנינו במשנה שכל מתנות הדם שעל מזבח הפנימי כולן מעכבות, \u0003לפיכך אם נתן כולן כתיקנן\u0004 ואחת שלא כתיקנה, במחשבת חוץ לזמנו — פסול ואין בו כרת. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת מנחות, לגבי הקטרת הקומץ והלבונה, ששניהם מתירים את המנחה באכילה: אם \u0003פיגל בקומץ ולא בלבונה, בלבונה ולא בקומץ,\u0004 שהקטיר אחד מהם על מנת לאכול את השיריים למחר, \u0003ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת,\u0004","\u0003וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר,\u0004 גם בקומץ וגם בלבונה.","\u0003אמר ר' שמעון בן לקיש: לא תימא\u0004 \u0005[אל תאמר]\u0006 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' מאיר,\u0004 שאמר שהוא פיגול, הריהו משום \u0003דקסבר\u0004 \u0005[שהוא סבור]\u0006 בכלל \u0003ש\u0004\u0003מפגלין\u0004 גם אם חשב מחשבת חוץ לזמנו רק \u0003בחצי מתיר,\u0004 \u0003אלא הכא במאי\u0004 \u0003עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון ש\u0004תחילה \u0003נתן את הקומץ\u0004 על המזבח כדי להקטירו \u0003במחשבה\u0004 לאכול את השיריים למחר, \u0003ו\u0004אחר כך נתן את \u0003הלבונה בשתיקה\u0004 כלומר, בסתם. וטעם הדבר, כי \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' מאיר: \u0003כל העושה\u0004 — \u0003על דעת ראשונה הוא עושה,\u0004 ומה שעשה בלבונה עשה על דעת מחשבת חוץ לזמנו שחישב תחילה בקומץ.","\u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק, לומד ריש לקיש דבר זה? \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששונה]\u0006 התנא במשנתנו: \u0003לפיכך אם נתן\u0004 \u0003כולן כתיקנן ואחת שלא כתיקנה\u0004 — \u0003פסול ואין בו כרת,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 אם נתן \u0003אחת\u0004 בתחילה \u0003שלא כתיקנה,\u0004 במחשבת חוץ לזמנו, \u0003וכולן כתיקנן\u0004 — \u0003פיגול.\u0004","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אילימא רבנן\u0004 \u0005[אם תאמר\u0006 כשיטת \u0005חכמים]\u0006 בענין מי שפיגל בקומץ ולא בלבונה — \u0003הא אמרי רבנן\u0004 \u0005[הרי אמרו חכמים]\u0006 בפירוש: \u0003אין מפגלין בחצי מתיר,\u0004 והרי נתן מתנה אחת כתיקנה! \u0003אלא\u0004 בהכרח שיטת \u0003ר' מאיר\u0004 היא, שאמר כי גם אם פיגל בקומץ ולא בלבונה — פיגול הוא.","\u0003ו\u0004אולם \u0003אי טעמא\u0004 \u0005[אם הטעם]\u0006 של \u0003ר' מאיר משום\u0004 ש\u0003מפגלין בחצי\u0004 \u0003מתיר הוא,\u0004 אם כן \u0003אפילו כדקתני נמי\u0004 \u0005[כפי ששונה\u0006 התנא \u0005גם כן],\u0006 כשנתן כולן כתיקנן ואחת שלא כתיקנה — גם אז פיגול הוא לדעת ר' מאיר, שהרי פיגל בחצי מתיר! אלא \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]:\u0006 \u0003כל העושה\u0004 — \u0003על דעת ראשונה הוא עושה?\u0004 ולפיכך, אם פיגל במתנה ראשונה — פיגול הוא, ואם ראשונה כתיקנה — אינו פיגול.","\u0003אמר ר' שמואל בר יצחק: לעולם\u0004 אפשר לומר כי משנתנו שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שאין מפגלים בחצי מחיר, \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003\"כתיקנן\"\u0004 שנאמר שם? \u0003כתיקנן לפיגול\u0004 כלומר, שעשה אותן במחשבה שמפגלת. ומשמיעה לנו המשנה כי למרות שעשה את כל ההזאות הראשונות במחשבת פיגול — אין אומרים שהאחרונה שנעשתה בשתיקה נעשתה על דעת הראשונה.","ומקשים: \u0003והא מדקתני\u0004 \u0005[והרי מ\u0006מה \u0005ששנה]:\u0006 \u0003לפיכך אם נתן כולן כתיקנן ואחת שלא כתיקנה\u0004 — \u0003פסול ואין בו כרת,\u0004 ומשמע שבגלל האחת שנעשתה שלא כתיקנה הוא נפסל, \u0003מכלל\u0004 דברים אלה אתה למד שהביטוי \u0003\"תיקנה\" להכשירה הוא דאתא\u0004 \u0005[להכשר הוא שבא],\u0006 ולא לפיגול!","\u0003אמר רבא:\u0004 בכל זאת ניתן לפרש \"כתיקנן\" למחשבת פיגול, כי \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"שלא כתיקנה\"?\u0004 הרי זו מחשבת \u0003חוץ למקומו,\u0004 שיש בה כדי לפסול את הקרבן, וכך לגרום שלא יהא זה פיגול, שהרי לא קרבו כל המתירים כראוי. \u0003רב אשי אמר:\u0004 יש לפרש \"שלא כתיקנה\" במשנתנו — שנתן מתנה אחת במחשבת \u0003שלא לשמו\u0004 של הקרבן, ובחטאת מחשבה שלא לשמה פוסלת.","ומקשים: על כל פנים, \u0003מכלל\u0004 הדברים אתה למד \u0003דכי לא עביד לה\u0004 \u0005[שכאשר אינו עושה אותה]\u0006 במחשבת \u0003חוץ למקומו ושלא לשמו,\u0004 אלא בשתיקה — \u0003מחייב\u0004 \u0005[חייב]\u0006 ופיגול הוא, וזה ודאי אינו כשיטת החכמים!","ודוחים: אין לדייק מלשון הלכה זו, לפי שלא נאמרה בדווקא, אלא \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילה],\u0006 בחטאת החיצונה, שאם חישב במתנה הראשונה חוץ לזמנו ובמתנה שניה חוץ למקומו הרי זה \u0003פיגול וחייבין עליו כרת, תנא נמי סיפא\u0004 \u0005[שנה גם כן בסוף]\u0006 בחטאת פנימית מקרה דומה, שאם חישב באחרונה מחשבת חוץ למקומו (או שלא לשמו) — \u0003פסול ואין בו כרת.\u0004 ואין לדייק מכאן שאם לא חשב מחשבה כזאת, אלא עשה בשתיקה, שפיגול הוא. על כל פנים, דחינו את ראייתו של ריש לקיש בהבנת דברי ר' מאיר.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דבריו, ממה ששנינו בברייתא: \u0003במה דברים אמורים?\u0004 שעושה פיגול גם כאשר חושב מחשבת חוץ לזמנו רק במתנה הראשונה — \u0003בדמים הניתנין על מזבח החיצון,\u0004 שמתנה אחת מתירה את הקרבן,"],["\u0003אבל דמים הניתנין\u0004 בפנים, בקדש הקדשים, על הפרוכת ו\u0003על המזבח הפנימי, כגון ארבעים ושלש\u0004 מתנות \u0003של\u0004 פר ושעיר של \u0003יום הכיפורים, ואחד עשר\u0004 מתנות \u0003של פר כהן משיח, ואחד עשר של פר העלם דבר של ציבור,\u0004 אם \u0003פיגל בין בראשונה ובין בשניה ובין בשלישית\u0004 כלומר, בכל אחת מסדרת הזאות שיש בהם, כגון בפר יום הכיפורים — בקדש הקדשים, על הפרוכת, ועל מזבח הזהב, \u0003ר' מאיר אומר: פיגול\u0004 הוא, \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר.\u0004","\u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003פיגל בין בראשונה בין בשניה בין בשלישית, ופליג\u0004 \u0005[וחולק]\u0006 ר' מאיר. ואם כשפיגל בשניה או בשלישית הוא פיגול, משמע שהוא סבור שמפגלים בחצי מתיר. שלא כהבנת ריש לקיש, הסבור שלדעתו הוא פיגול רק כשעשה את הראשונה בפיגול, והשאר נעשה על דעת ראשונה!","\u0003אמר רב יצחק בר אבין: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — לא שפיגל בעבודת ההזאה, שיש בה חצאי מתיר, אלא \u0003כגון שפיגל בשחיטה\u0004 שלאחר שנתן דם הפר בפנים נשפך הדם, והוצרך לשחוט פר נוסף, כדי להזות על הפרוכת. ופעם נוספת הוצרך לשחוט לצורך הזאות על המזבח. \u0003דחד\u0004 \u0005מתיר\u0006 \u0005[ש\u0006השחיטה \u0005מתיר אחד]\u0006 \u0003הוא,\u0004 ובכל פעם פיגל בעבודה שלימה, ולא בחצי מתיר. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של החכמים]\u0006 שאמרו שאינו פיגול?","\u0003אמר רבא: מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה — שיטת \u0003ר' אליעזר היא, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 לענין איסור הקרבה בחוץ: \u0003הקומץ, והלבונה, והקטורת, ומנחת כהנים, ומנחת כהן משיח, ומנחת נסכים,\u0004 כל אלו, שדינם ליקרב על המזבח, \u0003שהקריב מאחת מהן\u0004 אפילו \u0003כזית בחוץ\u0004 — הרי זה \u0003חייב,\u0004 שהקטרה שיש בה שיעור כזית הקטרה שלימה היא, \u0003ור' אליעזר פוטר עד שיקריב את כולן.\u0004 הרי לשיטתו, אף שעשה עבודה שלימה לעצמה, הואיל ואין העבודה נגמרת בה — אינו חייב עליה. וכך הוא לגבי שחיטה של כל אחד מן הפרים, לצורך כל אחת מסדרת ההזאות, אין בה כרת עד שיפגל בכולן. ומקשים: כיצד יכול אתה לפרש כן את דעת ר' אליעזר לגבי הזאות הדם?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: ומודה ר' אליעזר בדמים\u0004 שחייב אפילו העלה מקצת מן הדם בחוץ. \u0003דתנן\u0004 \u0005[ששנינו]\u0006 במשנה, \u0003ר' אליעזר ור' שמעון אומרים:\u0004 אם נשפך דם הקרבן (פר או שעיר של יום הכיפורים) אפילו באמצע מחזור אחד של הזאות (כגון של הפרוכת) ושחטו קרבן חדש, \u0003ממקום שפסק\u0004 כשנשפך הדם — \u0003משם הוא מתחיל\u0004 וממשיך ומשלים את המתנות. משמע שלדעתו כל אחת מהזאות הדם עומדת לעצמה ומפגלים בה, וזו בוודאי אינה דעת חכמים החולקים על ר' מאיר בברייתא!","\u0003אלא אמר רבא:\u0004 לדעת ריש לקיש, הכוונה בברייתא אינה שפיגל בראשונה או בשניה או בשלישית, אלא \u0003כגון שפיגל בראשונה\u0004 (בקודש הקדשים), \u0003ושתק בשניה\u0004 (בפרוכת), \u0003וחזר ופיגל בשלישית\u0004 (במזבח הזהב).","ויש בה חידוש לדעת ר' מאיר, הסבור שהעושה על דעת ראשונה עושה, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שבמתנה השניה \u0003על דעת ראשונה הוא\u0004 ממשיך לעשות, \u0003מיהדר פיגולי\u0004 \u0005[לחזור ולפגל]\u0006 במפורש \u0003בשלישית למה לי?\u0004 ומן הסתם לא פיגל בשניה — על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת אנו רואים את השתיקה במתנה השניה כהמשך המחשבה הראשונה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: מידי\u0004 \u0005[כלום]\u0006 \u0003\"שתק\u0004 בשניה\" \u0003קתני\u0004 \u0005[שנה\u0006 שם\u0005]?\u0006 והרי זהו עיקר החידוש לפי הסברו של רבא!","\u0003אלא אמר רב אשי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שפיגל בראשונה\u0004 (בקודש הקדשים) \u0003ובשניה\u0004 (על הפרוכת) \u0003ובשלישית\u0004 (על קרנות המזבח), ואת ההמשך עשה בשתיקה, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 ש\u0003כל העושה על דעת ראשונה הוא עושה, מהדר פיגולי בכל חדא וחדא\u0004 \u0005[לחזור ולפגל בכל אחת ואחת]\u0006 \u0003למה לי? קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין זה נימוק מספיק, ועדיין רואים אותו כעושה על דעת מחשבה ראשונה."],["ומקשים: כיצד יכול אתה לפרש שפיגל בראשונה וגם בשניה וגם בשלישית? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"בין\u0004 בראשונה \u0003בין\u0004 בשניה\" \u0003קתני\u0004 \u0005[שנה].\u0006 משמע שפיגל באחת מהן ולא \u0005בכולן! ומעירים: אכן,\u0006 \u0003קשיא\u0004 \u0005[קשה],\u0006 שאין הלשון מתיישבת היטב.","ושבים לדון בברייתא העוסקת בדמים הפנימיים. \u0003אמר מר\u0004 \u0005[החכם],\u0006 אם פיגל באחת מסדרת ההזאות, כגון זו שבקודש הקדשים, \u0003ר' מאיר אומר: פיגול וחייבין עליו כרת,\u0004 למרות שאת ההמשך עשה בשתיקה. ושואלים: \u0003מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003כרת לא מיחייב\u0004 \u0005[אינו חייב]\u0006 על מחשבת פיגול \u0003עד שיקרבו כל מתיריו\u0004 של הקרבן, שצריך לגמור את סדר העבודה, ובכלל זה זריקת הדם, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כהרצאת כשר\u0004 כדרך שעושים כדי שיירצה קרבן כשר, \u0003כך הרצאת פסול, מה הרצאת כשר\u0004 אינו מרצה \u0003עד שיקרבו כל מתיריו, אף הרצאת פסול\u0004 אין הפסול חל עליו \u0003עד שיקרבו כל מתיריו.\u0004","\u0003והא\u0004 \u0005[וזה]\u0006 דם פר ושעיר של יום הכיפורים, \u0003כיון דחשיב ביה\u0004 \u0005[שחשב בו]\u0006 מחשבת חוץ לזמנו \u0003בפנים\u0004 כשהיזה בקודש הקדשים, והרי זו הזאה \u0003פסולה\u0004 — \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003לא אדי דמי\u0004 \u0005[היזה\u0006 הוא \u0005נחשב],\u0006 שהרי אפילו מתנה אחת מעכבת בחטאת פנימית. ואם כן \u0003כי הדר מדי\u0004 \u0005[כאשר\u0006 הוא \u0005חוזר\u0006 ו\u0005מזה\u0006 אחר כך\u0005]\u0006 \u0003בהיכל\u0004 (על הפרוכת ועל מזבח הזהב) \u0003—\u0004 \u0003מיא בעלמא הוא דקא אדי\u0004 \u0005[\u0006כאילו \u0005מים בלבד הוא מזה]\u0006 ולא דם הזאה. ואם כן לא קרבו מתיריו של הקרבן, ואין זה פיגול שחייבים עליו!","\u0003אמר רבה: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בארבעה פרים ובארבעה שעירים\u0004 שלאחר שפיגל בהזאות של קודש הקדשים נשפך הדם, ושוב לא השתמש באותו דם להמשך ההזאה, וכך נשלמה עבודת ההזאה שבפנים, וקרב המתיר כראוי. והוצרך לשחוט פר ושעיר אחר לצורך המשך ההזאות בהיכל, ולאחר שהשלים את ההזאות שעל הפרוכת ופיגל בהן שוב נשפך הדם, וכן על קרנות מזבח הזהב, וכן על טהרו של מזבח הזהב. ונמצא שכל אחד מן המתירים קרב כראוי.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר \u0003בפר אחד ושעיר אחד\u0004 — \u0003לפיגולו\u0004 הרי הוא \u0003מרצה\u0004 כלומר, אף על פי שאחר שפיגל בפנים אין זה נחשב עוד לריצוי, מכל מקום מכיון שהוא גומר את סדר העבודה הרי זה מועיל לענין פיגול.","ועוד שנינו באותה ברייתא שנותן \u0003ארבעים ושלש\u0004 מתנות ביום הכיפורים. ושואלים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ארבעים ושבע!\u0004 ומשיבים: \u0003הא כמאן דאמר\u0004 \u0005[זה ששנינו ארבעים ושלוש כ\u0006דעת \u0005מי\u0006 שאומר\u0005]\u0006 \u0003מערבין לקרנות\u0004 שמערבים את דם הפר והשעיר לפני הנתינה על קרנות המזבח, \u0003והא כמאן דאמר\u0004 \u0005[וזה כמי שאומר]\u0006 \u0003אין מערבין לקרנות,\u0004 ומזה ארבע מתנות מדם הפר ועוד ארבע מדם השעיר, ורק אחר כך מערב ומזה על טהרו של מזבח.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שיש \u0003ארבעים ושמונה\u0004 מתנות! ומשיבים: \u0003הא כמאן דאמר\u0004 \u0005[זה,\u0006 ששנינו ארבעים ושמונה, \u0005כמי שאומר]\u0006 \u0003שיריים\u0004 של דם הנזרק בפנים, שנשפכים על יסוד מזבח החיצון \u0003מעכבין,\u0004 ולכן צריכים להוסיף את שפיכת השיריים כמתנה נוספת, \u0003הא כמאן דאמר\u0004 \u0005[זה כמי שאומר]\u0006 \u0003אין שיריים מעכבין,\u0004 ואז יש רק ארבעים ושבע.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת ר' שמעון בן לקיש בהבנת דברי ר' מאיר, שאין מפגלים בחצי מתיר, ממה ששנינו בברייתא בעניין פיגול במנחה: \u0003במה דברים אמורים\u0004 שאם חישב מחשבת חוץ לזמנו בעבודה אחת מעבודות המנחה, שהוא פיגול, למרות שעשה את השאר בשתיקה — כאשר חישב מחשבת חוץ לזמנו \u0003בקמיצה\u0004 של הקומץ, או \u0003במתן\u0004 הקומץ ב\u0003כלי,\u0004 או \u0003בהילוך\u0004 הקומץ למזבח.","\u0003אבל בא לו להקטרה, נתן את הקומץ במחשבה\u0004 חוץ לזמנו \u0003ואת הלבונה בשתיקה, או שנתן את הקומץ בשתיקה ואת הלבונה במחשבה\u0004 — \u0003ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר.\u0004","\u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]\u0006 את המקרה השני, שנתן \u0003את הקומץ בשתיקה ו\u0004אחר כך \u0003את הלבונה במחשבה, ופליג\u0004 \u0005[וחולק]\u0006 על כך ר' מאיר. משמע שלדעתו אין הדברים תלויים במחשבה הראשונה, האם היא היתה מחשבת פיגול, אלא בסברה שמפגלים בחצי מתיר! ומתרצים: \u0003אימא\u0004 \u0005[אמור,\u0006 הבן\u0005]\u0006 כך: או שנתן את הקומץ בשתיקה, ו\u0003כבר נתן\u0004 מתחילה \u0003את הלבונה במחשבה.\u0004 וגם במקרה זה הוא פיגול, משום שעל דעת ראשונה עשה.","ודוחים: \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003דהיינו רישא\u0004 \u0005[שזוהי\u0006 ההלכה \u0005הראשונה]\u0006 בדיוק! \u0003ועוד, הא תניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 אחרת, ששם מפורש: \u0003ואחר כך\u0004 נתן את הלבונה במחשבה! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר לדעת ריש לקיש, הסבור שאין ר' מאיר אומר שמפגלים בחצי מתיר.","\u0003ואלו דברים שאין חייבין עליהם\u0004 כרת \u0003משום פיגול,\u0004 כי איסור הפיגול חל רק על דבר שיש לו דבר אחר המתיר אותו בהקרבה או באכילה, והדברים השנויים כאן אין דבר אחר המתיר אותם, או שהם עצמם מתירים דבר אחר: \u0003הקומץ\u0004 שמתיר את המנחה, \u0003והקטרת\u0004 שמוקטרת כולה, ואין לה מתיר, \u0003והלבונה\u0004 המתירה את המנחה,"],["\u0003ומנחת כהנים\u0004 שעולה כולה כליל ואין בה קמיצה (ראה ויקרא ו, טז), ולכן אין לה מתירים, \u0003ו\u0004כן \u0003מנחת כהן משיח\u0004 (מנחת חביתין) שמקריב הכהן הגדול בכל יום מחצית ממנה בבוקר ומחצית בערב (ויקרא ו, טו), שכולה כליל, \u0003והדם\u0004 שהוא המתיר את הקרבנות כולם. \u0003והנסכים הבאין בפני עצמן\u0004 כקרבן לעצמו, שאין להם מתירים, \u0003דברי\u0004 \u0003ר' מאיר. וחכמים אומרים: אף\u0004 הנסכים \u0003הבאין עם\u0004 קרבן \u0003הבהמה\u0004 אין בהם פיגול.","\u0003לוג שמן של מצורע\u0004 — \u0003ר' שמעון אומר: אין חייבין עליו משום פיגול,\u0004 שהרי אין לו מתירים. \u0003ור' מאיר אומר: חייבין עליו משום פיגול,\u0004 משום \u0003שדם האשם\u0004 של המצורע הוא \u0003מתירו,\u0004 שרק אחר כך מזים את השמן, והוא ניתן לכהנים, \u0003ו\u0004הכלל הוא: \u0003כל שיש לו מתירין בין לאדם\u0004 (לאכילה) \u0003בין למזבח\u0004 (להקרבה) — \u0003חייבין עליו משום פיגול.\u0004","ומפרטים: \u0003העולה\u0004 — \u0003דמה מתיר את בשרה למזבח ו\u0004את \u0003עורה לכהנים. עולת העוף\u0004 — \u0003דמה מתיר את בשרה\u0004 (ועורה בכלל זה) \u0003למזבח. חטאת העוף\u0004 — \u0003דמה מתיר את בשרה לכהנים. פרים הנשרפים ושעירים הנשרפים\u0004 (כגון פר העלם דבר ושעירי עבודה זרה), שבשרם אינו עולה למזבח ואינו נאכל לכהנים, אלא נשרף מחוץ למקדש — \u0003דמן מתיר את אימוריהן ליקרב.\u0004","\u0003ר' שמעון אומר:\u0004 פרים ושעירים אלה אין בהם פיגול, כי דמם ניתן בהיכל, ו\u0003כל שאינו\u0004 אין דמו ניתן \u0003על המזבח החיצון כשלמים\u0004 שבהם נאמר דין פיגול (ויקרא ז, יח) — \u0003אין חייבין עליו משום פיגול.\u0004","\u0003אמר עולא: קומץ פיגול שהעלו\u0004 והקטירו \u0003על גבי המזבח\u0004 — \u0003פקע\u0004 \u0003פיגולו ממנו,\u0004 והטעם לדבר: \u0003אם אחרים מביא לידי פיגול, הוא\u0004 \u0003עצמו לא כל שכן?\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 הרי אין זה טעם למה שנאמר מתחילה שפקע פיגולו! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 \u0005אומר]:\u0006 \u0003אם אינו מתקבל,\u0004 אם אין הקטרתו נחשבת הקטרה ראויה, \u0003היאך מביא אחרים לידי פיגול?\u0004 שהרי אין חייבים על המנחה משום פיגול עד שיקרב הקומץ כראוי.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו\u0006 בכך\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 רוצה ללמדנו ש\u0003אין חייבין עליו משום פיגול,\u0004 הלוא \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003אלו דברים שאין חייבין עליהם משום פיגול: הקומץ, והקטרת, והלבונה, ומנחת כהנים, ומנחת כהן משיח, ומנחת נסכים, והדם.\u0004 ואם כן, גם אם לא עלה על המזבח אין חייבים עליו!","\u0003אלא\u0004 רוצה להשמיע לנו שהוא בכלל אלו ש\u0003אם עלו\u0004 על המזבח \u0003לא ירדו\u0004 — הלוא \u0003תנינא\u0004 \u0005[שנינו\u0006 כבר\u0005]\u0006 דבר זה, להלן: \u0003הלן\u0004 בשר שעבר עליו הלילה, \u0003ו\u0004בשר \u0003היוצא\u0004 מחוץ לעזרה, \u0003ו\u0004הבשר \u0003הטמא, ושנשחט\u0004 (והוא הדין אם נקמץ) \u0003חוץ לזמנו וחוץ למקומו\u0004 — \u0003אם עלו לא ירדו!\u0004","\u0003ואלא\u0004 רוצה לומר שהוא בכלל אלו ש\u0003אם ירדו\u0004 מן המזבח, בכל זאת \u0003יעלו\u0004 אותם שנית — \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו]\u0006 שאין הדין כן, אלא \u0003כשם שאם עלו\u0004 \u0003לא ירדו, כך אם ירדו לא יעלו!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 הלכה זו שאמר עולא, אלא במקרה \u0003שמשלה בהן האור\u0004 כלומר, שכבר התחיל אותו קומץ להישרף קצת ונפל מן המזבח, ואמר עולא שיחזרו ויעלוהו, מאחר שפקע פיגולו ממנו.","ומקשים: \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003אמרה עולא חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר עולא: לא שנו,\u0004 שדברים שנפלו מן המזבח אין מעלים אותם, \u0003אלא\u0004 במקרה \u0003שלא משלה בהן האור\u0004 (האש), \u0003אבל משלה\u0004 \u0003בהן האור יעלו!\u0004 ומשיבים: בכל זאת יש חידוש בדבר, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006"],["כגון \u0003אבר דמחבר\u0004 \u0005[ש\u0006הוא \u0005מחובר],\u0006 שהוא יחידה אחת, ואפשר לומר שכיון שחלק ממנו נשרף הרי כולו כבר \"לחמו של מזבח\", ויעלה כולו, \u0003אבל קומץ דמיפרת\u0004 \u0005[ש\u0006הוא \u0005מפורד],\u0006 שמא מה שמשלה בו האש חוזרים ומעלים, והשאר \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יעלה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם בקומץ הדין כן, ויעלה כולו.","\u0003אמר רב אחאי: הלכך\u0004 \u0005[משום כך],\u0006 שהקומץ נחשב כדבר אחד, \u0003האי\u0004 \u0005[זה]\u0006 \u0003קומץ פיגול דפלגיה מחית אארעא\u0004 \u0005[שחציו מונח על הקרקע]\u0006 \u0003ופלגיה אסקיה\u0004 \u0005[וחציו העלהו]\u0006 ל\u0003מערכה, ומשלה בו האור\u0004 — \u0003מסיקנא ליה לכוליה\u0004 \u0005[מעלים אותו את כולו]\u0006 \u0003לכתחלה.\u0004","\u0003אמר ר' יצחק אמר ר' יוחנן: הפיגול והנותר והטמא שהעלן לגבי\u0004 \u0003מזבח\u0004 — \u0003פקע איסור מהן. אמר רב חסדא\u0004 בתמיהה: \u0003מרי דיכי\u0004 \u0005[בעל\u0006 ההלכה \u0005הזו],\u0006 וכי \u0003מזבח מקוה טהרה\u0004 הוא שמטהר את הטמא?! \u0003אמר ר' זירא:\u0004 מדובר במקרה \u0003שמשלה בהן האור,\u0004 ואז הם בטלים מאיסורם הראשון.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' יצחק בר ביסנא\u0004 מברייתא, שבה שנינו: \u0003אחרים אומרים:\u0004 הכתוב \u0003\"וטמאתו עליו\"\u0004 (ויקרא ז, כ), מדבר ב\u0003מי שטומאה פורחת ממנו\u0004 כלומר, שעכשיו היא עליו, ויכולה לצאת ממנו על ידי מקוה, והוא אדם שנטמא. \u0003יצא בשר\u0004 קדשים שנטמא, שאינו בכלל כתוב זה, לפי \u0003שאין טומאה פורחת ממנו\u0004 שאם נטמא אין לו טהרה. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי ר' יוחנן, \u0003הרי\u0004 גם בשר \u0003טומאה פורחת ממנו על ידי האור\u0004 של המזבח!","\u0003אמר רבא:\u0004 מה שנאמר שם שטומאה פורחת ממנו — \u0003על ידי מקוה קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ולא בדרך אחרת. ומקשים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003מקוה כתיב\u0004 \u0005[כתוב\u0006 שם\u0005]?\u0006 הלוא נאמר בדרך הכללה שטומאה פורחת ממנו! \u0003אלא אמר רב פפא: בבשר שלמים עסקינן\u0004 \u0005[עוסקים אנו]\u0006 באותו כתוב, \u0003דלא חזי\u0004 \u0005[ש\u0006הוא \u0005אינו ראוי]\u0006 \u0003להקרבה,\u0004 שבשר השלמים נאכל ואינו עולה למזבח, ואין העלאתו על המזבח מועילה להפקיע את טומאתו.","\u0003רבינא אמר:\u0004 גם אם טומאה פוקעת מבשר שעלה על המזבח, פסוק זה אינו מדבר עליו, \u0003כי\u0004 \u0003\"וטמאתו עליו\"\u0004 כוונתו \u0003מי שטומאה פורחת ממנו כשהוא שלם,\u0004 ש\"עליו\" משמעו — כמות שהוא, בשלמותו, \u0003יצא בשר\u0004 שהוא \u0003דבר שאין טומאה פורחת כשהוא שלם, אלא כשהוא חסר,\u0004 כשמושל בו האור על המזבח.","\u0003גופא\u0004 \u0005[\u0006ודנים \u0005לגופה]\u0006 של הברייתא שהבאנו קודם, שבה מנסים חכמים להוכיח כי הכתוב \"והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו ונכרתה הנפש ההיא מעמיה\" (ויקרא ז, כ), מדבר בטמא האוכל בשר שלמים. וכך שנויה הברייתא: \u0003\"וטמאתו עליו\"\u0004 — \u0003בטומאת הגוף\u0004 טומאת האדם האוכל (ולא טומאת הבשר הנאכל) \u0003הכתוב מדבר.\u0004","ויש לשאול: \u0003אתה אומר: בטומאת הגוף, או אינו אלא\u0004 מדובר \u0003בטומאת בשר,\u0004 שהרי \"הנפש\" היא לשון נקבה, והבשר הוא לשון זכר, ולפיכך משמע שהבשר הוא הטמא! \u0003נאמר כאן: \"טמאתו\u0004 עליו\", \u0003ונאמר להלן: \"טמאתו (עליו) [בו]\",\u0004 (\"כל הנוגע במת... ולא יתחטא... טמא יהיה עוד טומאתו בו\", במדבר יט, יג), \u0003מה להלן בטומאת הגוף הכתוב מדבר, אף כאן בטומאת הגוף הכתוב מדבר.\u0004","\u0003ר' יוסי אומר\u0004 ראיה אחרת: \u0003הואיל ונאמרו\u0004 בפסוק זה (ויקרא ז, כ) \u0003קדשים בלשון רבים\u0004 (\"שלמים\") \u0003ונאמרה טומאה בלשון יחיד\u0004 (\"עליו\"), משמע כי \"וטומאתו עליו\" \u0003בטומאת הגוף הכתוב מדבר\u0004 ולא בטומאת השלמים\u0003.\u0004 \u0003רבי אומר\u0004 ראיה אחרת: נאמר בפסוק שאחר כך \u0003\"ואכל\",\u0004 \"ונפש כי תגע בכל טמא... ואכל מבשר זבח השלמים\" (ויקרא ז, כא), ומכאן ש\u0003בטומאת הגוף הכתוב מדבר. אחרים אמרו:\u0004 הביטוי \u0003\"וטמאתו עליו\"\u0004 הוא עצמו מוכיח שמדובר ב\u0003מי שטומאה פורחת ממנו\u0004 כגון אדם, שעכשיו טומאתו עליו, ויכולה היא לסור מעליו, \u0003יצא\u0004 מכלל זה \u0003בשר\u0004 שלאחר שנטמא \u0003אין טומאה פורחת ממנו.\u0004 עד כאן לשון הברייתא, ומעתה דנים בה.","\u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003רבי אומר: \"ואכל\"\u0004 — \u0003בטומאת הגוף הכתוב מדבר.\u0004 ותוהים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כלומר, מה משמעה של הוכחה זו מפסוק אחר? ומביאים בענין זה מה ש\u0003אמר רבא: כל קרא דלא מפרש ליה\u0004 \u0005[מקרא שאין מפרש אותו]\u0006 \u0003רב יצחק בר אבודימי, וכל מתניתא דלא מפרשא לה\u0004 \u0005[וכל משנה,\u0006 ברייתא, \u0005שאין מפרש אותה]\u0006 \u0003(רב) זעירי\u0004 — \u0003לא מיפרשא\u0004 \u0005[אינה מתפרשת],\u0006 שהם הפרשנים הגדולים למקרא ולמשנה.","\u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יצחק בר אבודימי:\u0004 בפסוק הבא (אליו התייחס רבי) נאמר \"ונפש כי תגע בכל טמא... ואכל מבשר זבח השלמים... ונכרתה הנפש ההיא מעמיה\", ובהתאם לכך נפרש כי גם בפסוק הקודם שאנו דנים בו, \u0003הואיל ופתח\u0004 בו \u0003הכתוב בלשון נקבה\u0004 (\"והנפש\") \u0003וסיים בלשון נקבה\u0004 (\"ונכרתה\") \u0003ולשון זכר באמצע\u0004 (\"וטמאתו עליו\"), משמע ש\u0003בטומאת הגוף הכתוב מדבר.\u0004","\u0003מתניתא\u0004 \u0005[הברייתא]\u0006 שרבא רומז לפירושו של זעירי עליה, אף היא באותו נושא של אכילת קדשים בטומאת הגוף. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין זה: \u0003אם נאמרו\u0004 \u0003קלות למה נאמרו חמורות, ואם נאמר חמורות למה נאמר קלות? אם נאמר קלות ולא חמורות, הייתי אומר: על הקלות\u0004 יהא חייב רק \u0003ב\u0004איסור \u0003לאו\u0004 (ובעונש מלקות) \u0003ועל החמורות\u0004 יתחייב \u0003במיתה, לכך נאמר חמורות. ואם נאמר חמורות ולא נאמרו קלות, הייתי אומר: על החמורות יהא חייב ועל הקלות יהא פטור\u0004 לגמרי, \u0003לכך נאמר קלות.\u0004 ברייתא זו סתומה היא, שאף שיודעים אנו שהיא עוסקת באכילת קדשים בטומאה, אין זה ברור בדיוק למה היא מתייחסת.","ומבררים: \u0003מאי\u0004 \u0005[מהן]\u0006 ה\u0003קלות ומאי\u0004 \u0005[ומהן]\u0006 ה\u0003חמורות? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003קלות\u0004 הן אכילת \u0003מעשר\u0004 שני בטומאת הגוף, \u0003חמורות\u0004 הן אכילת \u0003תרומה\u0004 בטומאת הגוף, ואילו היה נאמר בתורה האיסור רק באכילת מעשר ולא בתרומה, \u0003הייתי אומר\u0004 שהאוכל תרומה הוא \u0003במיתה?\u0004 והרי \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 שנאמר הכתוב בתרומה, \u0003הא\u0004 \u0005[הרי זו\u0006 ההלכה\u0005]\u0006 שהאוכל תרומה בטומאת הגוף דינו \u0003במיתה\u0004 בידי שמים!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות על הברייתא לפירוש זה: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא נאמר\u0004 חמורות אלא קלות, \u0003הייתי אומר\u0004 שעונשן של החמורות \u0003במיתה?\u0004 כיצד אפשר לומר כך? הלוא כלל הוא בדיני קל וחומר, \u0003דיו לבא מן הדין להיות כנדון\u0004 שאם למדים חמורות מקלות בקל וחומר, אין להחמיר בנדון יותר מן המקור. ואם דינו של טמא האוכל מעשר בלאו, כלומר בעונש מלקות — לא היה דינה של תרומה חמור ממנו!","\u0003אלא,\u0004 צריך לפרש ש\u0003קלות\u0004 הן \u0003טומאת שרץ, חמורות\u0004 הן \u0003טומאת מת,\u0004 שכן הכתוב באותה פרשה מונה את שתיהן: \"והנוגע בכל טמא נפש... או איש אשר יגע בכל שרץ\" (ויקרא כב, ד-ה).","ונברר: \u0003ובמאי\u0004 \u0005[במה]\u0006 מדובר? \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בתרומה\u0004 — \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003הוא במיתה,\u0004 שאין הבדל בהלכה במה נטמאו, אלא כל טמא האוכל תרומה חייב מיתה! \u0003ותו\u0004 \u0005[ועוד],\u0006 כיצד ניתן לפרש מה שנאמר שם: \u0003לכך נאמרו חמורות\u0004 — לומר שאינן במיתה, וכוונת הדברים שהן \u0003ב\u0004איסור \u0003לאו\u0004 (לא תעשה)? \u0003הא\u0004 \u0005[הרי]\u0006 תרומה \u0003במיתה היא! (\u0004ואי \u0005[ואם]\u0006 \u0003לא נאמר הייתי אומר במיתה? דיו לבא מן הדין להיות כנדון!)\u0004 הרי שלא ניתן לפרש קלות וחמורות באופן זה לגבי תרומה.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003באכילת מעשר\u0004 מדובר, גם על כך קשה:"],["\u0003אם לא נאמרו חמורות\u0004 (טומאת מת) \u0003הייתי אומר על החמורות במיתה? הא\u0004 \u0005[הרי]\u0006 אם לא היתה נאמרת טומאת מת \u0003מטומאת שרץ קאתיא\u0004 \u0005[באה,\u0006 נלמדת היא\u0005],\u0006 \u0003ודיו לבא מן הדין להיות כנדון,\u0004 בלאו, ולא יותר!","\u0003אמר זעירי\u0004 והסביר: \u0003קלות\u0004 הן \u0003טומאת שרץ, חמורות\u0004 — \u0003טומאת מת, והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003אילו נאמר טומאת שרץ ונאמר\u0004 שטמא שרץ האוכל \u0003מעשר\u0004 בלאו, \u0003ו\u0004האוכל \u0003תרומה\u0004 במיתה, \u0003ולא נאמרה\u0004 בפרשה זו \u0003טומאת מת, הייתי אומר:\u0004 הרי \u0003(קלות) על הקלות\u0004 אם טמא טומאת שרץ ואכל מעשר — חייב \u0003בלאו, ועל החמורות\u0004 אכל תרומה בטומאת שרץ \u0003במיתה.\u0004","ואפשר היה לומר: \u0003ומ\u0004תוך שב\u0003קלות על החמורות\u0004 (טומאת שרץ תרומה) \u0003במיתה\u0004 — \u0003חמורות נמי\u0004 \u0005[גם כן]\u0006 \u0003על הקלות\u0004 (טומאת מת במעשר) \u0003במיתה. לכך נאמרו חמורות\u0004 (טומאת מת) בכתוב זה, שמוזכר בו איסור לאו במעשר, לומר שגם לענין זה דין תרומה וקדשים לעצמו במיתה, ודין מעשר לעצמו בלאו.","שנינו במשנה: \u0003כל שיש לו מתירין בין לאדם בין למזבח\u0004 — \u0003חייבין עליו\u0004 \u0003משום פיגול.\u0004","ומביאים בענין זה מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדרשת הפסוק האמור בפיגול \"ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה\" וכו' (ויקרא ז, יח): \u0003או אינו מביא\u0004 לדין פיגול \u0003אלא כיוצא בשלמים, מה שלמים מיוחדים\u0004 שהם \u0003נאכלין לשני ימים ולילה אחד, אף כל נאכל לשני ימים ולילה אחד,\u0004 זבח ש","\u0003נאכל ליום ולילה\u0004 (כגון חטאת ואשם ובכור) \u0003מנין? תלמוד לומר\u0004 בפסוק: \u0003\"מבשר\u0004 זבח שלמיו\" כל שבשרו נאכל, לומר \u0003כל ששירין\u0004 שלו \u0003נאכלין\u0004 חייב עליו משום אכילת פיגול. ויש לשאול: \u0003עולה שאין שיריה נאכלין,\u0004 אלא כולה כליל, \u0003מנין? תלמוד לומר: \"זבח\"\u0004 לרבות כל מיני זבחים, כל קרבן שיש בו שחיטה.","\u0003מנין לרבות העופות,\u0004 שאינם נשחטים אלא נמלקים, \u0003והמנחות\u0004 הבאות מן הצומח, \u0003עד שאני מרבה\u0004 אפילו \u0003לוג שמן של מצורע? תלמוד לומר\u0004 לגבי אכילת קדשים בטומאת הגוף: \"ולא יחללו את שם קדשי \u0003אשר הם מקדישים לי\"\u0004 (ויקרא כב, ב),","\u0003ואתי\u0004 \u0005[ובא,\u0006 נלמד\u0005]\u0006 דין אכילת \u0003נותר\u0004 בגזירה שווה של \u0003\"חילול\" \"חילול\" מטומאה,\u0004 שכתוב בה חילול (\"ולא יחללו\", ויקרא כב, ב), ואף בנותר כתוב \"ואוכליו עונו ישא כי את קדש ה' חלל\" (ויקרא יט, ח). \u0003ואתי\u0004 \u0005[ובא,\u0006 נלמד\u0005]\u0006 \u0003פיגול\u0004 מגזירה שווה של המילים \u0003\"עון\" \"עון\" מנותר,\u0004 שנאמר בו \"עוונו ישא\" (ויקרא יט, ח), וגם בפיגול \"עוונה תשא\" (\u0003ויקרא\u0004 ז, יח).","ושואלים: \u0003ומאחר שסופו לרבות כל דבר,\u0004 על סמך גזירה שווה זו, \u0003למה נאמר\u0004 בפיגול \u0003שלמים מעתה? לומר לך:\u0004 על כל פנים צריך שיהא דומה לשלמים, \u0003מה שלמים מיוחדים\u0004 במה \u0003שיש להן מתירין בין לאדם\u0004 לאכילה, \u0003בין למזבח\u0004 להקרבה, \u0003אף כל שיש לו מתירין בין לאדם בין למזבח\u0004 כלומר, או לזה או לזה — \u0003חייבין עליהן משום פיגול.\u0004","ובכלל זה \u0003העולה\u0004 ש\u0003דמה מתיר את בשרה למזבח ועורה לכהנים, עולת העוף\u0004 — ש\u0003דמה מתיר את בשרה למזבח, חטאת העוף\u0004 — \u0003ש\u0004\u0003דמה מתיר את בשרה לכהנים, פרים הנשרפים ושעירים הנשרפים\u0004 — ש\u0003דמם מתיר את אימוריהן ליקרב.\u0004","\u0003ומוציא אני\u0004 על ידי ההשוואה לשלמים \u0003את הקומץ ואת הלבונה והקטרת, ומנחת כהנים ומנחת כהן משיח, ומנחת נסכים והדם,\u0004 שכל אלה אין להם מתירים לא לאדם ולא למזבח.","\u0003ר' שמעון אומר:\u0004 כך יש לדמות לשלמים, \u0003מה שלמים מיוחדין שיש בו\u0004 מתיר הניתן \u0003על מזבח החיצון\u0004 (הדם) \u0003וחייבין עליו, אף כל ש\u0004מתיריהם \u0003ישנן על מזבח החיצון חייבין עליו משום פיגול. יצאו פרים הנשרפים ושעירים הנשרפים, הואיל שאין\u0004 דמם ניתן \u0003על מזבח החיצון כשלמים\u0004 — \u0003אין חייבין עליו משום פיגול.\u0004","ומבארים קטעים מברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 או אינו מביא בכלל איסור פיגול אלא \u0003כיוצא\u0004 \u0003בשלמים.\u0004 ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הוא]?\u0006 \u0003בכור,\u0004 ש\u0003נאכל לשני ימים ולילה אחד.\u0004 ומקשים: \u0003במאי אתי\u0004 \u0005[במה,\u0006 באיזה דרך הוא \u0005בא,\u0006 נלמד\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004דרך הלימוד של \u0003מה מצינו\u0004 (בנין אב), הרי \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 את ההשוואה ולומר:","\u0003מה לשלמים שהן טעונין סמיכה ונסכים, ו\u0004יש בהם \u0003תנופת חזה ושוק,\u0004 שאין כל אלה בבכור!","\u0003אלא\u0004 הוא נלמד בדרך הלימוד של כלל ופרט וכלל, \u0003מ\u0004מה שנאמר בפסוק זה: \u0003\"אם האכל יאכל\u0004 מבשר זבח שלמיו\" (ויקרא ז, יח), \"האכל\" \"יאכל\" הם שני כללים, ו\"בשר זבח שלמיו\" הוא פרט, ולפי כללי מדרש ההלכה, במקרה של כלל ופרט וכלל, אתה דן לכל דבר שהוא מעין הפרט, כלומר בכור.","על כך יש להקשות: והרי \u0003הני תרי כללי דסמיכי אהדדי נינהו\u0004 \u0005[אלה שני כללים הסמוכים זה לזה הם],\u0006 ואין זה כלל ופרט וכלל! \u0003אמר רבא:\u0004 גם באופן זה למדים למה שהוא מעין הפרט, \u0003כדאמרי במערבא\u0004 \u0005[כמו שאומרים בארץ ישראל]:\u0006 \u0003כל מקום שאתה מוצא שני כללות הסמוכים זה לזה, הטל פרט\u0004 שכתוב אחריהם \u0003ביניהם ודונם בכלל ופרט,\u0004 ונמצא שיש כאן כלל ופרט וכלל.","שנינו שם: \u0003עד שאני\u0004 \u0003מרבה לוג שמן של מצורע\u0004 ששייריו נאכלים לכהנים. ומעירים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' מאיר היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לוג שמן של מצורע\u0004 — \u0003חייבין עליו משום פיגול,\u0004 אם פיגל באשם שהלוג בא עמו, \u0003דברי ר' מאיר.\u0004 אולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא שאנו דנים בה: \u0003ומוציא אני מנחת נסכים\u0004 הבאה עם כל קרבן שמן הבהמה, \u0003והדם,\u0004 שאין חייבים עליהם משום פיגול משום שאין להם מתירים. אם כן \u0003אתאן לרבנן\u0004 \u0005[הגענו\u0006 איפוא \u0005ל\u0006שיטת \u0005חכמים]\u0006 החולקים על ר' מאיר,","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נסכי\u0004 קרבן \u0003בהמה חייבין עליהן משום פיגול, מפני שדם הזבח מתירן ליקרב, דברי ר' מאיר. אמרו לו:\u0004 \u0003והלא אדם מביא את זבחיו היום ונסכין מיכן עד עשרה ימים,\u0004 ואם כן לא דם הזבח מתיר אותם! \u0003אמר להן: אף אני לא אמרתי\u0004 שמפגל \u0003אלא ב\u0004נסכים ה\u0003באין עם הזבח.\u0004 ואם כן יש בברייתא זו שתי שיטות סותרות!","\u0003אמר רב יוסף: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבי היא,\u0004 שהוא סבור כחכמים, שמנחת נסכים אינה ניתרת בדם הזבח. ואין לכן סתירה מלוג השמן, לפי \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003לוג שמן של מצורע\u0004 לא דם האשם מתירו, אלא \u0003מתנותיו\u0004 שזורק מן השמן עצמו \"לפני ה'\" (ראה ויקרא יד, טז) \u0003שרו ליה\u0004 \u0005[\u0006הם \u0005המתירות אותו]\u0006 כלומר, את שייריו, באכילה לכהנים. \u0003ומדמתנותיו שרו ליה\u0004 \u0005[ומכיון שמתנותיו מתירות אותו],\u0006 מטעם זה \u0003מתנותיו מפגלי ליה\u0004 \u0005[מפגלות אותו],\u0006 שאם הזה אותן על מנת שיאכלו הכהנים את שייריו למחר — הרי חייבים על אכילתו משום פיגול. ומנין שסבור רבי שמתנותיו של הלוג עצמו הן המתירות אותו?","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לוג שמן של מצורע מועלין בו\u0004 חייבים עליו משום מעילה \u0003עד שיזרוק הדם\u0004 של האשם, שאז הותר השמן לכהנים ושוב אין בו דין מעילה. \u0003נזרק הדם\u0004 — \u0003לא נהנין\u0004 (מדברי חכמים לפי שעדיין צריך ליתן ממנו לפני ה' ועל בהונות המצורע) \u0003ולא מועלין.\u0004","\u0003רבי אומר: מועלין\u0004 בו \u0003עד שיתן מתנותיו\u0004 שלו עצמו, שמתנותיו הן המתירות את שאר השמן לכהנים. \u0003ושוין\u0004 רבי וחכמים, \u0003שאסור\u0004 לוג זה \u0003באכילה\u0004 גם לדעת חכמים, \u0003עד שיתן מתן שבע\u0004 לפני ה' \u0003ו\u0004גם \u0003מתן\u0004 על \u0003בהונות\u0004 המצורע.","\u0003אמרוה\u0004 לשמועה זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה, אמר: גברא רבא\u0004 \u0005[אדם גדול]\u0006 \u0003כרב יוסף לימא כי הא מילתא\u0004 \u0005[יאמר דבר כזה]\u0006 שמתנות השמן מפגלות את שאר השמן?"],["\u0003הרי לוג\u0004 שמן \u0003הבא בפני עצמו,\u0004 שהביאו המצורע לאחר שהביא קרבנו, \u0003דלכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003מתנותיו\u0004 של הלוג עצמו \u0003שרו ליה\u0004 \u0005[מתירות אותו]\u0006 לכהנים, \u0003ו\u0004למרות זאת \u0003לא מפגלין ליה\u0004 \u0005[אינן מפגלות אותו]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לוג שמן של מצורע חייבין עליו משום פיגול, מפני שדם מתירו לבהונות, דברי ר' מאיר.\u0004","\u0003אמרו לו לר' מאיר: והלא אדם מביא אשמו עכשיו, ולוג\u0004 שמן \u0003מיכן ועד עשרה ימים,\u0004 משמע שלא הדם הוא המתיר! \u0003אמר להן\u0004 ר' מאיר: \u0003אף אני לא אמרתי\u0004 שחייבים על אכילת לוג שמן משום פיגול \u0003אלא\u0004 בלוג ה\u0003בא עם האשם.\u0004 הרי שאפילו לדעת ר' מאיר הסבור שמפגלים בלוג שמן — לא מתנותיו מפגלות אותו, אלא דם האשם!","\u0003אלא אמר ר' ירמיה: לעולם\u0004 ברייתא זו שיטת \u0003ר' מאיר היא, וסמי\u0004 \u0005[ומחוק]\u0006 \u0003מיכן\u0004 מנחת \u0003נסכים\u0004 מרשימת הדברים שאין בהם פיגול, כדי שלא תהיה סתירה. \u0003אמר אביי: לעולם לא תסמי\u0004 \u0005[אל תמחק],\u0006 \u0003ותנא\u0004 \u0005[ו\u0006התנא \u0005שונה]\u0006 \u0003לוג הבא עם האשם, והוא הדין לנסכים הבאין עם הזבח,\u0004 שסבור ר' מאיר שמפגלים בהם. \u0003והדר תנא\u0004 \u0005[וחוזר ושונה]\u0006 \u0003נסכים הבאין בפני עצמן\u0004 שאין מפגלים בהם, \u0003והוא הדין ללוג הבא לפני עצמו.\u0004","שנינו במשנה: \u0003חטאת העוף\u0004 — \u0003דמה מתיר את בשרה לכהנים.\u0004 ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שבשרה נאכל לכהנים? ומביאים לענין זה ברייתא \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי\u0004 על הכתוב בענין מתנות כהונה: \"וזה יהיה לך מקדש הקדשים מן האש כל קרבנם לכל מנחתם ולכל חטאתם ולכל אשמם אשר ישיבו לי קדש קדשים לך הוא ולבניך\" (במדבר יח, ט), והברייתא מסבירה מה באה לרבות התוספת \"כל\" בכל אחד מן הפרטים שבפסוק זה:","\u0003\"כל קרבנם\"\u0004 — \u0003לרבות לוג שמן של מצורע,\u0004 שניתן לכהנים למאכל. ומסבירה הגמרא מדוע יש צורך בריבוי מיוחד: כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003\"מן האש\" כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 בפסוק זה, \u0003והאי\u0004 \u0005[וזה]\u0006 לוג השמן, למרות שהוא קרבן, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מותר מן האש הוא,\u0004 שהרי לא הועלה ממנו דבר על המזבח, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת הוא לכהנים.","וממשיכה הברייתא: \u0003\"לכל מנחתם\"\u0004 \u0003—\u0004 \u0003לרבות מנחת עומר ומנחת הקנאות\u0004 (מנחת סוטה). ומסבירים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 כי הואיל ונאמר לגבי אכילת הכהנים מן הקדשים: \u0003\"ואכלו אותם אשר כפר בהם\"\u0004 (שמות כט, לג), ואם כן, רק דבר הבא לכפר ניתן להם לאכילה, ואלה אינם באים לכפר, כי \u0003מנחת העומר להתיר\u0004 את התבואה החדשה \u0003אתיא\u0004 \u0005[באה],\u0006 \u0003ומנחת קנאות לברר עון קאתיא\u0004 \u0005[באה],\u0006 כחלק מבדיקת המים המאררים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאף אלה בכלל המנחות הנאכלות לכהנים.","וממשיכה הברייתא: \u0003\"ולכל חטאתם\"\u0004 — \u0003לרבות חטאת העוף.\u0004 ומסבירים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שאינה נאכלת לפי ש\u0003נבילה היא,\u0004 שהרי היא נמלקת מן העורף (ויקרא ה, ח) ואינה נשחטת מן הצואר, כדין עוף של חולין, על כן משמיע לנו שהיא נאכלת לכהנים.","\u0003\"לכל אשמם\"\u0004 — \u0003לרבות אשם נזיר\u0004 שנטמא, \u0003ואשם מצורע.\u0004 ומסבירים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שאינם ניתנים לכהנים לאכילה, כיון ש\u0003להכשיר קאתו\u0004 \u0005[הם באים]\u0006 ולא לכפר, כי אשם נזיר מכשירו להתחיל מחדש את נזירותו, ואשם מצורע מכשירו לאכול קדשים, והרי נאמר \"ואכלו אותם אשר כופר בהם\" (שמות כט, לג\u0003),\u0004 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שהם נאכלים לכהנים.","ושואלים: \u0003אשם מצורע\u0004 כיצד יכול היית לומר שאין אוכלים אותו? \u0003בהדיא כתיב ביה\u0004 \u0005[במפורש כתוב בו]\u0006 שהכהנים אוכלים אותו (ויקרא יד, יג)! \u0003אלא,\u0004 כוונת הדברים היא: \u0003לרבות אשם נזיר,\u0004 לומר שדינו \u0003כאשם מצורע.\u0004","וממשיכה הברייתא: מה שנאמר \u0003\"אשר ישיבו\"\u0004 — \u0003זה גזל הגר\u0004 שהגוזל מאת הגר שאין יורשים כלל, צריך לתת לכהנים את הקרן והחומש, ונאמר כאן: \u0003\"לך הוא\"\u0004 — כלומר \u0003שלך יהיה,\u0004 ויהא כשלך לכל דבר, \u0003אפילו לקדש בו\u0004 \u0003את האשה.\u0004","ובענין פיגול בפרים הנשרפים ושעירים הנשרפים, שדמם ניתן על מזבח הפנימי, שלדעת התנא של משנתנו מפגלים בעבודתם, ולדעת ר' שמעון במשנה אין בהם פיגול, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 ובה דעה נוספת. \u0003ר' אלעזר אומר משום\u0004 (בשם) \u0003ר' יוסי הגלילי:\u0004 אם \u0003פיגל\u0004 בפרים הנשרפים ובשעירים הנשרפים \u0003בדבר הנעשה בחוץ\u0004 (בעזרה) — \u0003פיגל,\u0004 אם פיגל \u0003בדבר הנעשה בפנים\u0004 (בהיכל או בקדש הקדשים) — \u0003לא פיגל,\u0004","\u0003כיצד? היה עומד בחוץ\u0004 בזמן השחיטה, \u0003ואמר: \"הריני שוחט להזות מדמו למחר\u0004 בתוך ההיכל\" — \u0003לא פיגל,\u0004 שהמחשב \u0003מחשבה בחוץ ב\u0004נוגע ל\u0003דבר הנעשה בפנים לא פיגל.\u0004 וכן \u0003היה עומד בפנים\u0004 בזמן ההזאה, \u0003ואמר: \"הריני מזה\u0004 מדם החטאת \u0003על מנת להקטיר אימורים\u0004 על המזבח החיצון \u0003ולשפוך שירים\u0004 על יסוד המזבח החיצון \u0003למחר\"\u0004 — \u0003לא פיגל,\u0004 מפני \u0003ש\u0004חישב \u0003מחשבה בפנים בדבר הנעשה בחוץ.\u0004","\u0003אבל היה עומד בחוץ\u0004 בזמן השחיטה, \u0003ואמר: \"הריני שוחט לשפוך שירים למחר או להקטיר אימורים למחר\"\u0004 — \u0003פיגל, ש\u0004היא \u0003מחשבה בחוץ בדבר הנעשה בחוץ.\u0004","\u0003אמר ר' יהושע בן לוי: מאי קרא\u0004 \u0005[מה המקרא]\u0006 המלמד על זה? שנאמר בהרמת האימורים מפר כהן משיח, שהוא אחד מן הפרים הנשרפים: \u0003\"כאשר יורם משור זבח השלמים\"\u0004 (ויקרא ד, י), \u0003וכי מה למדנו משור זבח השלמים\u0004 \u0003מעתה?\u0004 שהרי נתפרש בשור זה כל מה שנתפרש שם!","\u0003אלא מקיש\u0004 (משווה הכתוב) \u0003פר כהן משיח לשור זבח השלמים, מה שור זבח השלמים\u0004 אין בו פיגול \u0003עד שיהו מעשיו ומחשבותיו על מזבח החיצון\u0004 שהרי שם זובחים אותו \u0003—\u0004 \u0003אף פר כהן משיח\u0004 אין בו פיגול \u0003עד שיהו מחשבותיו ומעשיו על המזבח החיצון.\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: הלכה כר' אלעזר שאמר משום ר' יוסי.\u0004","\u0003אמר רבא:\u0004"],["וכי פוסקים \u0003הלכתא למשיחא\u0004 \u0005[הלכה ל\u0006ימות \u0005המשיח]\u0006 כשיבנה המקדש? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה, כל שחיטת קדשים\u0004 (מסכת זבחים) \u0003לא לתני\u0004 \u0005[נשנה\u0006 ונלמד\u0005],\u0006 שהרי \u0003הלכתא למשיחא\u0004 \u0005[הלכה ל\u0006ימות \u0005המשיח]\u0006 \u0003הוא! אלא\u0004 לומדים זאת משום \u0003דרוש וקבל שכר, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נאמר: \u0003דרוש וקבל שכר!\u0004 אמר לו רב יוסף: \u0003הכי קאמינא לך\u0004 \u0005[כך אני אומר לך]:\u0006 \u0003הלכתא\u0004 \u0005[\u0006לקבוע \u0005הלכה]\u0006 \u0003למה לי?\u0004 והרי אין בזה צורך למעשה ומביאים \u0003לישנא אחרינא\u0004 \u0005[לשון\u0006 \u0003אחרת],\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הלכה קאמינא\u0004 \u0005[אני אומר],\u0006 שלקבוע הלכה בדבר כזה הוא תמוה.","\u0003קדשי גוים\u0004 שהקדישו כדי להקריבם לה' — \u0003אין חייבין עליהם משום\u0004 אכילת \u0003פיגול\u0004 אם נעשתה בהן עבודה במחשבת חוץ לזמנו, ולא משום אכילת \u0003נותר ו\u0004לא אם אכלם כשהוא \u0003טמא, והשוחטן בחוץ\u0004 — \u0003פטור,\u0004 אלו \u0003דברי ר' שמעון,\u0004 ואילו \u0003ר' יוסי מחייב.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003קדשי גוים\u0004 — \u0003לא נהנין\u0004 אסור ליהנות מהם, \u0003ו\u0004אולם \u0003לא מועלין\u0004 בהם, אין בהם דין מעילה. \u0003ואין חייבין עליהן משום פיגול,\u0004 ולא משום \u0003נותר ו\u0004לא משום \u0003טמא,\u0004","\u0003ואין\u0004 הם \u0003עושין תמורה\u0004 שאם אמר הגוי על בהמה שתהא תמורת בהמת הקדש — אין קדושה חלה עליה, \u0003ואין\u0004 הגוים \u0003מביאין נסכים\u0004 בפני עצמם, \u0003אבל קרבנן\u0004 של גוים \u0003טעון נסכים, דברי ר' שמעון.\u0004","\u0003אמר ר' יוסי: רואה אני בכולן\u0004 בכל הדברים הללו \u0003להחמיר,\u0004 לפי \u0003שנאמר בהן\u0004 גם בקרבנות הגוים \u0003\"לה'\"\u0004 (ויקרא כב, יח), משמע שהם כקדשי ה' לכל דבר, ולפיכך מועלים בהם, וחייבים עליהם משום פיגול נותר וטמא, ועושים תמורה. \u0003במה דברים אמורים? בקדשי מזבח, אבל בקדשי בדק הבית\u0004 שהתנדבו גוים — \u0003מועלין בהן.\u0004 עד כאן הברייתא, ומעתה דנים בה לפרטיה.","שנינו ש\u0003לא נהנין ולא מועלין\u0004 בקדשי גוים. ומסבירים: \u0003לא נהנין\u0004 — \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 שאסרו ליהנות מדבר שהוקדש לשמים,","\u0003ולא מועלין\u0004 אין חלים על כך דיני מעילה — \u0003דגמר\u0004 \u0005[שלומד]\u0006 בגזירה שווה \u0003מעילה\u0004 מן המילים \u0003\"חט\" \"חט\" מתרומה,\u0004 שבמעילה נאמר \"וחטאה בשגגה\" (ויקרא ה, טו), ובתרומה \"לא ישאו עליו חטא\" (ויקרא כב, ט), ו\u0003ב\u0004איסור לטמא \u0003תרומה כתיב\u0004 \u0005[נאמר]\u0006 \"ולא יחללו את קדשי \u0003בני ישראל\"\u0004 (ויקרא כב, טו), \u0003ולא\u0004 קדשי \u0003גוים\u0004 שאין חייבים על אכילת תרומת גוים בטומאה.","ועוד שנינו בברייתא: \u0003ואין חייבין עליו משום פיגול, נותר וטמא.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דאתי\u0004 \u0005[שבא,\u0006 נלמד\u0005]\u0006 \u0003פיגול\u0004 בגזירה שווה מן המילים \u0003\"עון\" \"עון\" מנותר,\u0004","\u0003ואתי\u0004 \u0005[ובא,\u0006 ונלמד\u0005]\u0006 \u0003נותר\u0004 בגזירה שווה \u0003\"חילול\" \"חילול\" מטומאה\u0004 (בנותר — \"את קדש ה' חלל\", ויקרא יט, ח. ובטומאה — \"ולא יחללו\", ויקרא כב, ב. בפיגול — \"עוונה תשא\", ויקרא ז, יח. ובנותר — \"עוונו ישא\", ויקרא יט, ח), \u0003ובטומאה כתיב\u0004 \u0005[נאמר]\u0006 \"וינזרו מקדשי \u0003בני ישראל\"\u0004 (ויקרא כב, ב) \u0003ולא גוים.\u0004","ועוד שנינו בברייתא: \u0003ואין\u0004 גוים \u0003עושין תמורה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דאיתקש\u0004 \u0005[שהוקש]\u0006 דין \u0003תמורה למעשר בהמה\u0004 (ויקרא כז, לג), \u0003ומעשר בהמה איתקש\u0004 \u0005[הוקש]\u0006 \u0003למעשר דגן, ובמעשר דגן כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"בני ישראל\"\u0004 (במדבר יח, כד) — \u0003ולא גוים.\u0004","ותוהים על לימוד זה: \u0003וכי דבר הלמד בהיקש חוזר ומלמד\u0004 בקדשים שוב \u0003בהיקש?\u0004 ומשיבים: אין לימוד זה כולו בקדשים, שהרי \u0003מעשר דגן חולין הוא\u0004 ואינו שייך לקדשים.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח למי שאומר]\u0006 כי לגבי כלל זה, \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מלמד אזלינן\u0004 \u0005[אנו הולכים]\u0006 שאם המלמד בהיקש הראשון הוא חולין, למרות שהלמד הוא קדשים — למדים מן הלמד בהיקש לקדשים. \u0003אלא למאן דאמר בתר למד אזלינן\u0004 \u0005[ל\u0006דעת \u0005מי שאומר: אחרי הלמד אנו הולכים],\u0006 ואם הוא בקדשים שוב אין לומדים ממנו בהיקש לקדשים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא\u0004 כך צריך לומר: \u0003מעשר בהמה חובה שאין קבוע לה זמן הוא, וחובה שאין לה זמן קבוע\u0004 — \u0003ישראל מייתו\u0004 \u0005[מביאים אותה],\u0006 \u0003גוים לא מייתו\u0004 \u0005[אין מביאים],\u0006 וכאמור, הוקשה תמורה למעשר בהמה.","ועוד שנינו: \u0003ואין\u0004 הגוים \u0003מביאין נסכים.\u0004 ומביאים מקור לדבר, ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת נסכים \u0003\"אזרח\"\u0004 (במדבר טו, יג), ללמד: \u0003אזרח\u0004 אדם מישראל \u0003מביא נסכים\u0004 בפני עצמם, \u0003ואין הגוי מביא נסכים. יכול לא תהא עולתו טעונה נסכים? תלמוד לומר: \"ככה\u0004 יעשה לשור האחד\" (במדבר טו, יא), לומר שכל קרבן חייב בנסכים.","ועוד שנינו בברייתא, \u0003אמר ר' יוסי: רואה אני בכולן להחמיר. במה דברים אמורים\u0004 שאין בקדשי גוים דין מעילה? \u0003בקדשי מזבח.\u0004 ותחילה מסבירים את דין המעילה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006","\u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כי גמרה\u0004 \u0005[כאשר למדה]\u0006 \u0003מעילה \"חט\" \"חט\" מתרומה,\u0004 ושם נאמר \"בני ישראל\", הרי זה \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003תרומה דקדישא\u0004 \u0005[שקדושה]\u0006 ב\u0003קדושת הגוף, אבל קדושת בדק הבית\u0004 שהיא \u0003קדושת דמים,\u0004 שאין הדבר עצמו קדוש אלא דמיו, שהוא עומד למכירה לצרכי בדק הבית — \u0003לא,\u0004 ואין בה מיעוט. ושבים לדון בדברי ר' יוסי \"רואה אני בכולן להחמיר\".","ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דם שנטמא וזרקו,\u0004 אם זרקו \u0003בשוגג\u0004 — \u0003הורצה\u0004 ועלה לרצון על המזבח,"],["אם זרקו \u0003במזיד\u0004 — \u0003לא הורצה\u0004 על ידי הציץ. \u0003במה דברים אמורים?\u0004 שהיה זה \u0003ב\u0004קרבן של \u0003יחיד, אבל בציבור, בין בשוגג בין במזיד\u0004 — \u0003הורצה. ובגוים, בין בשוגג ובין במזיד\u0004 — \u0003לא הורצה.\u0004","\u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב פפא: כמאן\u0004 \u0005[כמי]\u0006 נאמרה הלכה זו שבגוים לא הורצה? ש\u0003לא כ\u0004דעת \u0003ר' יוסי, דאי\u0004 \u0005[שאם]\u0006 לשיטת \u0003ר' יוסי, האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003בכולן אני רואה להחמיר,\u0004 משמע שהוא משווה דיני קרבנות גוים לדיני קרבנות ישראל!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא שיטת \u0003ר' יוסי, שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין הציץ: \"לרצון \u0003להם\"\u0004 (שמות כח, לח), לומר: \u0003להם\u0004 הוא מרצה \u0003ולא לגוים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא\u0004 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: אלא מעתה,\u0004 מה שנאמר בדין טומאה בקדשים: \u0003\"אשר הם מקדישים\"\u0004 (ויקרא כב, ב), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נדייק לדעת ר' יוסי: \u0003הם ולא גוים,\u0004 ולא יהיה דין טומאה בקדשי גוים? והרי בענין זה שמפורש בברייתא בוודאי אמר ר' יוסי שדינם כישראל!","\u0003אלא אמר רב אשי:\u0004 אין זה בגלל המיעוט במילה \"להם\", אלא משום שעניינו של הציץ אינו שייך בהם, שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בציץ: \u0003\"לרצון להם\"\u0004 (שמות כח, לח), \u0003וגוים\u0004 הרי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני הרצאה\u0004 (ריצוי) \u0003נינהו\u0004 \u0005[הם].\u0006","אף אותם \u0003דברים\u0004 שמנינו במשנה הקודמת (מב,ב) \u0003שאין חייבים עליהם\u0004 על אכילתם כרת \u0003משום\u0004 אכילת \u0003פיגול\u0004 אם חישב בקרבן מחשבת חוץ לזמנו, לפי שאין להם מתירים, כגון הקומץ והלבונה והקטורת, \u0003חייבין עליהן\u0004 כרת \u0003משום\u0004 אכילת \u0003נותר\u0004 אם עבר זמנו של הקרבן, \u0003ומשום\u0004 אכילת \u0003טמא,\u0004 שאם אכלם כשהוא טמא — חייב כרת, ואם נטמאו ואכלם — חייב מלקות, \u0003חוץ מן הדם. ר' שמעון מחייב\u0004 בדין טומאה רק \u0003בדבר שדרכן לאכול\u0004 כגון קומץ המנחה, \u0003אבל העצים והלבונה והקטורת\u0004 שאין דרכם להיאכל — \u0003אין חייבין עליו משום טומאה\u0004 אם אוכלם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול לא יהו חייבין משום טומאה אלא על דבר שיש לו מתירין בין לאדם\u0004 או \u0003בין למזבח?\u0004","\u0003ו\u0004לכאורה \u0003דין\u0004 (קל וחומר) \u0003הוא: ומה פיגול שהוא בקביעה\u0004 שאם אכל בשוגג מביאים עליו חטאת קבועה, כשבה או שעירה, \u0003ובידיעה אחת\u0004 שכדי לחייבו חטאת די במה שנודע לו רק לאחר זמן שחטא בשגגה, \u0003ולא הותר מכללו\u0004 שאין מצב בו מותר לאכול פיגול — בכל זאת \u0003אין חייבין עליו אלא על\u0004 אכילת \u0003דבר שיש לו מתירין בין לאדם בין למזבח,\u0004","\u0003טומאה\u0004 אכילת קדשים כשהוא טמא, שדינה קל יותר, \u0003שהיא\u0004 לא בחטאת קבועה, אלא \u0003ב\u0004קרבן \u0003עולה ויורד\u0004 לפי מצבו הכלכלי של החוטא, שאם הוא עני מביא קרבן עוף, או אפילו מנחה (ראה ויקרא ה, ו-יג), \u0003ובשתי ידיעות\u0004 שכדי לחייבו בקרבן צריך שידע בטומאה מתחילה וישכח ויחטא, וידע שוב בטומאה לאחר המעשה, \u0003והותרה מכללה\u0004 בציבור, שציבור שרובו טמא עושה קרבנו בטומאה — \u0003אינו דין שאינו חייב אלא על דבר שיש לו\u0004 \u0003מתירין בין לאדם בין למזבח?\u0004","\u0003תלמוד לומר\u0004 בדיני אכילת קדשים בטומאה: \"וינזרו מקדשי בני ישראל... \u0003אשר הם מקדישים לי\"\u0004 (ויקרא כב, ב), להדגיש שעל כל דבר שמקדישים חייבים משום אכילה בטומאה.","\u0003יכול\u0004 יהא חייב על אכילת קדשים בטומאה \u0003מיד\u0004 לאחר הקדשתם? \u0003תלמוד לומר:\u0004 \"כל איש אשר \u0003יקרב\u0004 מכל זרעכם אל הקדשים\" (ויקרא כב, ג), והוא כפי מה ש\u0003אמר ר' אלעזר\u0004 בהסבר כתוב זה: \u0003וכי יש נוגע שהוא חייב,\u0004 כפי שמשמע מפשטות הכתוב, שכל הנוגע (\"יקרב\") בקדשים בטומאתו יתחייב? והרי רק האוכל בטומאה הוא החייב כרת!","\u0003אלא מה תלמוד לומר \"יקרב\"?\u0004 יש כאן רמז להקרבה, והרי זה כאילו אומר: איש אשר יקריב קדשים, ויאכלם. ואם כן \u0003בהוכשר [בשר] ליקרב\u0004 \u0003הכתוב מדבר. הא כיצד\u0004 מוכשר הקדש להיקרב? מה ש\u0003יש לו מתירין\u0004 — חייבים עליו \u0003משיקרבו מתירין\u0004 שלו, דבר ש\u0003אין לו מתירין\u0004 — מוכשר ליקרב \u0003משיקדש בכלי\u0004 שרת לצורך הקרבתו.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לענין \u0003טומאה\u0004 שחלה גם על דבר שאין לו מתירים, \u0003נותר מנלן\u0004 \u0005[מנין לנו]\u0006 שחייבים עליו בדבר שאין לו מתירים? ומשיבים: \u0003אתי\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 בגזירה שווה של \u0003\"חילול\" \"חילול\" מטומאה\u0004 שכתוב בה \"ולא יחללו\" (ויקרא כב, ב), ובנותר כתוב \"את קדש ה' חלל\" (ויקרא יט, ח).","ושואלים: \u0003ו\u0004מדוע לא \u0003לילף\u0004 \u0005[נלמד]\u0006 בגזירה שוה \u0003\"עון\" \"עון\" מפיגול\u0004 שכתוב בו \"עוונה תשא\" (ויקרא ז, יח), ובנותר כתוב \"עוונו ישא\" (ויקרא יט, ח), ונשווה את הנותר לדין פיגול, שחייבים רק על דבר שיש לו מתירים?","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003מטומאה הוי ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 דין נותר, \u0003שכן\u0004 הוא דומה לה בשלושה עניינים בשונה מפיגול, והם \u0003גז\"ל סימן\u0004 כלומר, פסול שהוא ב\u0003ג\u0004 וף הקרבן, שלא כמו בפיגול שהוא במחשבה. ואין פסולם נקבע כפיגול על ידי \u0003ז\u0004 ריקת הדם.","ובשניהם נאמר חי \u0003ל\u0004ול. ומשיבים: \u0003אדרבה\u0004 להיפך, \u0003מפיגול הוה ליה\u0004 \u0003למילף\u0004 \u0005[היה לו ללמוד]\u0006 דין נותר, \u0003שכן\u0004 גם הוא כפיגול, לא \u0003נותר\u0004 מכללו כמו טומאה, וגם לו אין ריצוי על ידי ה\u0003ציץ,\u0004 ושניהם שייכים בקרבן \u0003טהור,\u0004 ופסולם תלוי \u0003בזמן,\u0004 והם פסול של הדבר ה\u0003קרב,\u0004 ולא כמו בטומאה של האדם המקריב. \u0003והני נפישן\u0004 \u0005[ואלה\u0006 צדדי ההשוואה לפיגול \u0005מרובים]\u0006 יותר משל טומאה!","\u0003אלא\u0004 יש לחזור ממה שאמרנו, ולומר כי דין נותר נלמד \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003לוי\u0004 בענין זה, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי\u0004 על הפסוק \"וינזרו מקדשי בני ישראל\" (ויקרא כב, ב) האמור באיסור אכילת קדשים בטומאה: \u0003מנין שאף בפסול זמן הכתוב מדבר\u0004 ולא רק בפסול טומאה? \u0003תלמוד לומר: \"ולא יחללו את קדשי בני ישראל\"\u0004 (ויקרא כב, טו),"],["\u0003בשני חילולין הכתוב מדבר, אחד פסול נותר, ואחד פסול טומאה.\u0004","שנינו במשנה: \u0003חוץ מן הדם\u0004 שאין חייבים עליו משום טומאה ומשום נותר. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ולצורך זה מביאים תחילה דיון אחר, ששאלו: מה טעם אין דין מעילה בדם? \u0003אמר עולא, אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין דם: \u0003\"ואני נתתיו לכם\u0004 על המזבח לכפר\" (ויקרא יז, יא), ו\"לכם\" בא לומר: \u0003שלכם יהא,\u0004 ואין בו דין מעילה.","\u0003דבי\u0004 \u0005[\u0006החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה],\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לכפר\"\u0004 (ויקרא יז, יא), להדגיש: \u0003לכפרה נתתיו ולא\u0004 \u0003למעילה.\u0004","\u0003ר' יוחנן אמר, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כי הדם \u0003הוא\u0004 בנפש יכפר\" (ויקרא יז, יא), והמלה \"הוא\" יש בה הדגשה, לומר: הריהו נשאר כפי שהוא — \u0003הוא\u0004 דינו \u0003לפני כפרה\u0004 (זריקת הדם על המזבח) \u0003כלאחר כפרה: מה אחר כפרה אין בו\u0004 \u0003מעילה,\u0004 שכבר ניתן ממנו לגבוה, ונעשתה מצוותו, \u0003אף לפני כפרה אין בו מעילה.\u0004","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 להיפך, \u0003לאחר כפרה\u0004 יהיה דינו \u0003כלפני כפרה, מה לפני כפרה יש\u0004 \u0003בו מעילה, אף לאחר כפרה יש בו מעילה!\u0004 ומשיבים: דבר זה אי אפשר לומר, כי \u0003אין לך דבר שנעשית מצותו ומועלין בו.\u0004","ותוהים: \u0003ולא?\u0004 וכי אין דבר כזה? \u0003והרי תרומת הדשן\u0004 תרומה מדשן הקרבנות שנשרפו, שמצוה להניחה במקום מסויים אצל המזבח, והיא אסורה בהנאה ומועלים בה!","ומשיבים: אין מקום ללמוד משם לכל דין אחר, \u0003משום דהוי\u0004 \u0005[שהריהם]\u0006 \u0003תרומת הדשן ובגדי כהונה\u0004 של כהן גדול ביום הכיפורים, שצריך לגונזם, ואסור להשתמש בהם לאחר שעבד בהם, \u0003שני כתובין הבאין כאחד,\u0004 שבשניהם נאמר בתורה דין זה, \u0003וכל שני כתובים הבאין כאחד אין מלמדין\u0004 לשאר דברים.","ושואלים: \u0003הניחא לרבנן דאמרי\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים שאומרים]\u0006 שהכתוב \"ופשט את בגדי הבד אשר לבש בבואו אל הקודש \u0003והניחם שם\"\u0004 (ויקרא טז, כג) — \u0003מלמד שטעונין\u0004 בגדי הכהונה \u0003גניזה,\u0004 ולכן מועלים בהם.","\u0003אלא לר' דוסא\u0004 ש\u0003אמר: מותרות הן לכהן הדיוט\u0004 (שהרי הם בגדי לבן, כבגדי כהן הדיוט), ומה שנאמר \"והניחם שם\" בא לומר \u0003ובלבד\u0004 \u0003שלא ישתמש בהן\u0004 כהן גדול \u0003ליום הכפורים אחר,\u0004 ולשיטתו לא נאמרה בהם מעילה, ואם כן, אין כאן שני כתובים הבאים כאחד — \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע, לדעת ר' יוחנן, לא נלמד מתרומת הדשן שיש מעילה בדם לאחר שנעשית מצוותו?","ומשיבים: \u0003משום דהוי\u0004 \u0005[שהריהם]\u0006 \u0003תרומת\u0004 \u0003הדשן ועגלה ערופה\u0004 שמועלים בה לאחר עריפתה, \u0003שני כתובין הבאין כאחד\u0004 בענין זה, \u0003וכל\u0004 \u0003שני כתובין הבאין כאחד אין מלמדין.\u0004","ומקשים: \u0003הניחא למאן\u0004 \u0003דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003תרי מיעוטי כתיבי\u0004 \u0005[שני מיעוטים כתובים]\u0006 בענין זה, \u0003הכא כתיב\u0004 \u0005[כאן,\u0006 בעגלה, \u0005נאמר]:\u0006 \"העגלה \u0003הערופה\"\u0004 (דברים כא, ו), להדגיש שדין זה הוא רק במקרה זה, \u0003והתם כתיב\u0004 \u0005[ושם,\u0006 בתרומת הדשן, \u0005נאמר]:\u0006 \u0003\"ושמו\"\u0004 (ויקרא ו, ג) רק אותו בלבד, ולא אחר כיוצא בו.","עד כאן הדיון בדברי ר' יוחנן, ומעתה יש לשאול: \u0003ותלתא קראי\u0004 \u0005[ושלושה מקראות]\u0006 \u0003בדם,\u0004 שדייקו מהם שאין בו מעילה, \u0003למה לי?\u0004","אחד \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003ממעילה,\u0004 אחד למעט \u0003מ\u0004דין \u0003נותר, ו\u0004אחד למעט \u0003מ\u0004דין \u0003טומאה,\u0004 ללמד שכולם אינם שייכים בדם.","ומעירים: \u0003אבל פיגול\u0004 שאינו שייך בדם \u0003לא צריך קרא\u0004 \u0005[מקרא\u0006 מיותר\u0005],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 לעיל: \u0003כל שיש לו מתירין, בין לאדם בין\u0004 \u0003למזבח\u0004 — \u0003חייבין עליו משום פיגול, ודם גופיה\u0004 \u0005[עצמו]\u0006 \u0003מתיר\u0004 \u0003הוא,\u0004 ואין לו מתיר, ולכן אין בו פיגול.","במשנה הובאה מחלוקת בענין דין טומאה בקדשים שאינם נאכלים. ומביאים בענין זה מה ש\u0003אמר ר' יוחנן: שלשה כריתות\u0004 שנאמרו \u0003בשלמים\u0004 למי שאוכלם בטומאה (ויקרא ז, כ. ז, כא. כב, ג), \u0003למה?\u0004"],["\u0003אחת לכלל\u0004 (\"אשר יקרב אל הקדשים\", ויקרא כב, ג), \u0003ואחת לפרט\u0004 (\"מזבח השלמים\", ויקרא ז, כ), ללמוד ממנו לשאר קדשי מזבח במידת דבר שהיה בכלל ויצא מן הכלל, שמלמד על הכלל כולו. \u0003ואחת\u0004 (ויקרא ז, כא) \u0003ל\u0004רבות \u0003דברים שאינן נאכלין\u0004 כגון עצים ולבונה, שגם האוכל אותם כשהוא טמא חייב כרת.","ושואלים: \u0003ול\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 במשנתנו: \u0003דברים שאין נאכלין אין חייבין עליהם משום טומאה, לאיתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 לרבות \u0003חטאות הפנימיות,\u0004 שדמן ניתן בפנים.","\u0003שכן\u0004 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר ר' שמעון: כל ש\u0004דמו \u0003אינו\u0004 ניתן \u0003על\u0004 ה\u0003מזבח החיצון כשלמים אין חייבין עליו משום פיגול,\u0004 הייתי אומר ש\u0003משום טומאה נמי לא ליחייב\u0004 \u0005[גם כן לא יתחייב\u0006 עליו\u0005],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שחייב על חטאות הפנימיות משום טומאה.","שנינו במשנה: \u0003נומי\u0004 \u0005[אמר]\u0006 \u0003ר' שמעון מחייב\u0004 משום טומאה דווקא \u0003את\u0004 האוכל דבר \u0003שדרכו לאכול,\u0004 אבל לא עצים ולבונה וקטורת. ואילו חכמים מחייבים משום טומאה על הכל. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 שני זוגות האמוראים, \u0003ר' יוחנן וריש לקיש, ר' אלעזר ור' יוסי בר' חנינא, חד מהאי זוזא וחד מהאי זוזא\u0004 \u0005[אחד מזוג זה ואחד מזוג זה],\u0006","\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מחלוקת\u0004 שנחלקו חכמים על ר' שמעון היא \u0003בטומאת בשר\u0004 כלומר, הדבר הנאכל, שלדעת חכמים האוכל עצים או לבונה כשהם טמאים — לוקה, וכפי שלמדו מריבוי הכתובים באיסור \"והבשר אשר יגע בכל טמא לא יאכל... והבשר\" (ויקרא ז, יט), \u0003אבל בטומאת הגוף\u0004 של האוכל, שלא נתרבו שם בכתוב — \u0003דברי הכל אינו לוקה.\u0004","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כמחלוקת בזו\u0004 כפי שנחלקו על ר' שמעון בטומאת הנאכל, \u0003כך מחלוקת בזו\u0004 כך נחלקו עליו בטומאת האוכל, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון דקרינא ביה\u0004 \u0005[שאנו קוראים בו]\u0006 בדבר שאינו נאכל: \u0003\"והבשר אשר יגע בכל טמא\"\u0004 (ויקרא ז, יט), שמרבים מפסוק זה את הדברים שאינם נאכלים, שאסור לאוכלם כשהם טמאים — \u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 גם את הכתוב הסמוך אליו \u0003\"וטמאתו עליו\u0004 ונכרתה\" (ויקרא ז, כ), העוסק בטומאת הגוף של האוכל.","ומעירים: \u0003רב טביומי מתני הכי\u0004 \u0005[היה שונה כך]\u0006 סוגיה זו, כמו שאמרנו. ואילו \u0003רב כהנא מתני הכי\u0004 \u0005[היה שונה כך],\u0006 בדרך אחרת: \u0003חד מהאי זוזא וחד מהאי זוזא אסיפא\u0004 \u0005[אחד מזוג זה ואחד מזוג זה\u0006 נחלקו \u0005על סופה\u0006 של המשנה\u0003],\u0004 כלומר, בפירוש דברי ר' שמעון, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מחלוקת\u0004 מה שר' שמעון חולק על חכמים, ואינו מחייב על עצים ולבונה משום טומאה — \u0003בטומאת הגוף, אבל בטומאת בשר\u0004 כשהעצים והלבונה עצמם טמאים — \u0003דברי הכל לוקה. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כמחלוקת בזו כך\u0004 \u0003מחלוקת בזו,\u0004 ובכל מקרה ר' שמעון פוטר.","\u0003אמר רבא: מסתברא כמאן דאמר\u0004 \u0005[מסתבר כ\u0006דעת \u0005מי שאומר]\u0006 \u0003כמחלוקת בזו כך מחלוקת בזו,\u0004 ובכל מקרה פוטר ר' שמעון, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון דלא קרינא ביה\u0004 \u0005[ש\u0006לדעת ר' שמעון \u0005אין אנו קוראים בו]\u0006 בדבר שאינו נאכל \u0003\"וטמאתו עליו ונכרתה\", לא קרינן ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 אין הוא בכלל מה שנאמר \u0003\"והבשר אשר יגע\u0004 \u0003בכל טמא לא יאכל\",\u0004 ואינו לוקה על כך.","ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 שהכתוב \u0003\"והבשר\"\u0004 המופיע מיד אחר איסור זה, והוא מיותר — הרי זה בא \u0003לרבות עצים ולבונה,\u0004 משמע שאפילו אלה מקבלים טומאה! ומשיבים: אין זה אלא \u0003לפוסלה בעלמא\u0004 \u0005[ל\u0006ענין \u0005פסול בלבד],\u0006 אבל אין זו טומאה ממש לחייב על כך מלקות.","\u0003לשם ששה דברים הזבח נזבח: לשם זבח\u0004 כלומר, לשם אותו זבח שזובחים אותו, \u0003לשם זובח\u0004 לשמו של אותו אדם שמקריבים עבורו, \u0003לשם השם\u0004 להקריבו לקדוש ברוך הוא, \u0003לשם אשים\u0004 כדי שייאכל על ידי אש המזבח, \u0003לשם ריח, לשם ניחוח, והחטאת והאשם\u0004 אף נזבחים \u0003לשם\u0004 כפרה על אותו \u0003חטא.\u0004","\u0003אמר ר' יוסי: אף מי שלא היה בלבו לשם אחד מכל אלו\u0004 והקריב סתם — הרי זה \u0003כשר, שהוא תנאי בית דין\u0004 שיעשה כך לכתחילה, \u0003לפי\u0004 \u0003שאין המחשבה הולכת אלא אחר העובד,\u0004 וכדי שלא ייפסל הקרבן במחשבה.","בענין האמור במשנתנו \u0003אמר רב יהודה אמר רב\u0004 שיש לדרוש כך את הפסוק בענין קרבן עולה: \"עולה אשה ריח ניחוח לה'\" (ויקרא א, ט). \u0003\"עולה\"\u0004 — \u0003לשם עולה, לאפוקי\u0004 \u0005[להוציא]\u0006 שמקריב אותה \u0003לשם שלמים,\u0004 ש\u0003לא\u0004 יעשה כן. \u0003\"אשים\"\u0004 (\"אשה\") — שמקריב \u0003לשם אשים,\u0004 שייאכלו על ידי אש המזבח, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003כבבא\u0004 \u0005[צלי אש]\u0006 שמתכוון שיהיו האימורים (או העולה) רק נצלים על האש, ש\u0003לא\u0004 יעשה כן.","\u0003\"ריח\"\u0004 — \u0003לשם ריח, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003אברים\u0004 \u0003ש\u0004קודם \u0003צלאן ו\u0004אחר כך \u0003העלן\u0004 על המזבח, ש\u0003לא\u0004 יעשה על מנת כן, וכפי ש\u0003אמר רב יהודה אמר רב: אברים שצלאן והעלן אין בהן משום ריח.\u0004","\u0003\"ניחוח\"\u0004 — כלומר, \u0003לשם הנחת רוח\u0004 שיעלו לרצון לקדוש ברוך הוא, \u0003\"לה'\"\u0004— שיהא זה \u0003לשם מי שאמר והיה העולם.\u0004","\u0003אמר רב יהודה אמר רב: חטאת ששחטה לשם עולה\u0004 — \u0003פסולה,\u0004 כמבואר בראש המסכת, שחטאת ששחטה שלא לשמה נפסלת לגמרי. אבל אם שחטה \u0003לשם חולין\u0004 — \u0003כשרה. אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב?\u0004 שנאמר: \u0003\"ולא יחללו את קדשי בני ישראל\"\u0004 (ויקרא כב, טו), לומר \u0003קדשים מחללין קדשים\u0004 (אם חשב להקריב קדש אחר), \u0003ואין חולין מחללין קדשים.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבה\u0004 ממה ששנינו במשנתנו, \u0003אמר ר' יוסי: אף מי שלא היה בלבו לשם אחד מכל אלו\u0004 — \u0003כשר, שהוא תנאי בית דין.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003שלא היה בלבו כלל\u0004 אלא שחט סתם, \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003היה בלבו לשם חולין\u0004 — הרי הוא \u0003פסול!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא כך, שאם \u0003לא היה\u0004 בלבו \u0003כלל\u0004 — הרי זה קרבן \u0003כשר ומרצה, הא\u0004 \u0005[אבל]\u0006 אם \u0003היה בלבו לשם חולין\u0004 — הקרבן אמנם \u0003כשר,\u0004 אבל \u0003אינו מרצה,\u0004 שבכל זאת הוא קרבן פגום, ולכך התכוון גם רב בדבריו.","\u0003אמר ר' אלעזר:\u0004 אמנם \u0003חטאת ששחטה לשם חולין\u0004 — \u0003כשרה,\u0004 כדברי רב, אבל אם שחטה \u0003משום חולין\u0004 שסבור היה שהיא בהמת חולין — הרי היא \u0003פסולה,\u0004 שהרי נמצא כעושה מעשה שחיטה סתם, ולא כעובד בקודש. והוא \u0003כדבעא מיניה\u0004 \u0005[כמו ששאל אותו]\u0006 \u0003שמואל מרב הונא:\u0004"],["\u0003מנין למתעסק בקדשים\u0004 כלומר, השוחט קדשים לא מתוך כוונה, אלא כמתעסק בדברים אחרים, \u0003שהוא פסול?\u0004 אמר לו, \u0003שנאמר: \"ושחט את בן הבקר לפני ה'\"\u0004 (ויקרא א, ה), והרי מדובר שם על בן הבקר, אלא שיש כאן הדגשה — \u0003עד שתהא שחיטה לשם בן בקר,\u0004 ולא כמעשה חיתוך בלבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לרב הונא: \u0003זו בידינו היא,\u0004 דבר זה אני יודע שמצוה לעשות כן, אבל \u0003לעכב מנין?\u0004 מנין שאם שחט כמתעסק הרי הוא פסול? \u0003אמר ליה\u0004 \u0005[לו],\u0006 מתוך ששנה הכתוב ואמר: \u0003\"לרצנכם תזבחהו\"\u0004 (ויקרא יט, ה), כלומר, \u0003לדעתכם\u0004 מתוך דעת וכוונה \u0003זביחו\u0004 \u0005[זבחו].\u0006","","שנינו במשנה: \u0003שאין המחשבה הולכת אלא אחר העובד.\u0004 ומעירים: \u0003מתניתין דלא כי האי תנא\u0004 \u0005[משנתנו\u0006 היא \u0005שלא כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר' יוסי: שמעתי שהבעלים מפגלין\u0004 כלומר, שאף הבעלים יכולים לעשות פיגול במחשבתם. \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר בר' יוסי?\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והקריב המקריב\u0004 קרבנו לה'\" (במדבר טו, ד), הרי שבעל הקרבן הוא הקרוי \"המקריב\". \u0003אמר אביי: ר' אלעזר בר' יוסי ור' אליעזר, ור' שמעון בן אלעזר,\u0004 הולכים בשיטה אחת, \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003סבירא להו\u0004 \u0005[סבורים הם]\u0006 שגם כאשר מדובר בשני אנשים שונים \u0003זה מחשב וזה עובד הויא\u0004 \u0005[הרי היא]\u0006 \u0003מחשבה,\u0004 כאילו חשבה העושה. \u0003ר' אלעזר בר' יוסי\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 שהבעלים מחשבים ומפגלים, אף שהכהן הוא העובד. \u0003ר' אליעזר\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השוחט לגוי\u0004 עבור גוי — \u0003שחיטתו כשרה,\u0004 שישראל מותר לאכול מבהמה זו, \u0003ור' אליעזר פוסל,\u0004 משום שמחשבת הגוי שהיא בסתם לעבודה זרה, פוסלת את השחיטה. \u0003ר' שמעון בן אלעזר\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003כלל אמר ר' שמעון בן אלעזר\u0004 לענין הלכות שבת: \u0003כל\u0004 \u0003שאין כשר להצניע\u0004 שאינו דבר חשוב שרגילים לשמור ולהצניע אותו, \u0003ואין\u0004 אנשים \u0003מצניעין כמוהו\u0004 בשיעור קטן כל כך, ובדרך כלל אין חייבים על הוצאתו מרשות לרשות, אם \u0003הוכשר לזה\u0004 לאדם מסויים נחשב הדבר ראוי לשמירה \u0003והצניעו, ובא אחר והוציאו\u0004 מרשות לרשות, מכל מקום \u0003נתחייב זה\u0004 המוציא \u0003במחשבה של זה\u0004 המצניע, שעבורו הוא דבר חשוב.","","","","ומעירים: \u0003תרוייהו\u0004 \u0005[שניהם],\u0006 ר' אליעזר ור' שמעון בן אלעזר, למרות שדיברו בעניינים אחרים, שחיטה עבור גוי והוצאה בשבת, \u0003אית להו\u0004 \u0005[יש להם,\u0006 מקבלים\u0005]\u0006 את דעתו של \u0003ר' אלעזר בר' יוסי\u0004 בענין מחשבה בקדשים, והטעם שאנו סבורים כן: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בחוץ\u0004 בענייני חולין \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 לשיטתם שמחשבה של אדם אחד מועילה לגבי פעולתו של \u0005אחר,\u0006 \u0003בפנים\u0004 בקדשים, שנתפרש לנו שמחשבה מועלת בהם (\"לא יחשב\") \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ואילו \u0003ר' אלעזר בר' יוסי לית להו דתרוייהו\u0004 \u0005[אין לו,\u0006 אינו מקבל, מה שאמרו \u0005שניהם],\u0006 כי \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בפנים הוא דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 שמחשבה פועלת גם במה שאדם אחר עובד, \u0003בחוץ לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 כן. וכן יש להבחין בין דעות שני החכמים האחרים, \u0003כי\u0004 \u0003ר' שמעון בן אלעזר אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003ר' אליעזר,\u0004 שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לענין \u0003שבת אמרינן\u0004 \u0005[אומרים אנו]\u0006 שמחשבה של אחד נוגעת למעשיו של אחר, \u0003בעבודה זרה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ואילו \u0003ר' אליעזר לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דעת \u0003ר' שמעון בן אלעזר,\u0004 כי \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בעבודה זרה הוא דאמרת\u0004 \u0005[שאתה אומר]\u0006 משום שעבודה זרה נאסרה \u0003כעין\u0004 עבודה הנעשית \u0003בפנים\u0004 עבודת הקדשים, ולכן אפשר לומר כי דווקא בה מחשבה פוסלת עבודתו של אחר, כמו קדשים, \u0003אבל שבת\u0004 — רק \u0003מלאכת מחשבת אסרה תורה\u0004 שאינו מתחייב אלא על מלאכה שיש בה מחשבה של העושה, והמוציא הרי לא חשב שהוא עושה מלאכה.","","","","","\u0003איזהו מקומן של זבחים?\u0004 כלומר, מהו המקום הראוי לעבודתם ולאכילתם של הזבחים השונים? \u0003קדשי\u0004 \u0003קדשים\u0004 כולם \u0003שחיטתן בצפון\u0004 העזרה.","ומפרטים את הקרבנות לסוגיהם: \u0003פר ושעיר של יום הכיפורים\u0004 — \u0003שחיטתן בצפון, וקיבול\u0004 (קבלת) \u0003דמן בכלי שרת\u0004 גם הוא \u0003בצפון, ודמן טעון הזיה על בין הבדים\u0004 של הארון שבקודש הקדשים, \u0003ועל הפרוכת\u0004 שבין הקודש לקודש הקדשים, \u0003ועל מזבח הזהב.\u0004 ובכל אותן הזיות, אפילו \u0003מתנה אחת מהן מעכבת,\u0004 ואם לא עשה את כולן נפסל הקרבן. \u0003שירי הדם\u0004 של קרבן זה \u0003היה שופך על יסוד מערבי של מזבח החיצון, ואם לא נתן\u0004 את השירים הללו \u0003לא עכב\u0004 את הקרבן.","\u0003פרים הנשרפים ושעירים הנשרפים\u0004 פר של כהן משיח (ראה ויקרא ד, א—יב), פר העלם דבר של ציבור (ויקרא ד, יג—כא), וכן שעיר שמביא הציבור בהעלם דבר של עבודה זרה (ראה במדבר טו, כב) — \u0003שחיטתן בצפון, וקיבול דמן בכלי שרת בצפון, ודמן טעון הזיה על הפרוכת ועל מזבח הזהב,\u0004"],["\u0003מתנה אחת מהן מעכבת. שירי הדם היה שופך על יסוד מערבי של מזבח החיצון, ואם לא נתן\u0004 את השיירים \u0003לא עיכב. אלו ואלו,\u0004 הן פר ושעיר של יום הכיפורים והן פרים ושעירים הנשרפים, \u0003נשרפין\u0004 אחר כך על \u0003בית הדשן\u0004 מקום מחוץ לירושלים ששם היו משליכים את דשן המזבח.","על המשפט הראשון במשנה: קדשי קדשים שחיטתן בצפון, שואלים: \u0003וניתני נמי\u0004 \u0005[ושישנה גם כן]:\u0006 \u0003וקיבול דמן בכלי שרת בצפון,\u0004 השווה בכל קדשי הקדשים! ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 בין קדשי הקדשים \u0003אשם מצורע,\u0004 ש\u0003קיבול דמו ביד הוא,\u0004 שמקבל הכהן חלק מדמו ביד, \u0003שייריה\u0004 \u0005[שייר אותו]\u0006 את הדין הזה, ולא הביאו במשנה.","ומקשים: \u0003ו\u0004כי \u0003לא\u0004 שנה שמקבל דמו של אשם מצורע בכלי? \u0003והא קתני לה לקמן\u0004 \u0005[והרי שנה את\u0006 הדבר \u0005הזה\u0006 במשנה \u0005לפנינו,\u0006 בהמשך\u0005]:\u0006 \u0003אשם נזיר ואשם מצורע\u0004 — \u0003שחיטתן בצפון, וקבול דמן בכלי שרת בצפון!\u0004","ומשיבים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 כששנה את משנתנו, \u0003סבר: קיבול דמו\u0004 של אשם מצורע הרי גם \u0003ביד הוא,\u0004 ולכן \u0003שייריה\u0004 \u0005[שייר אותו],\u0006 \u0003וכיון\u0004 שבאמת \u0003לא סגי ליה\u0004 \u0005[אפשר לו]\u0006 \u0003אלא\u0004 שיקבלו את דמו גם \u0003בכלי, הדר תנייה\u0004 \u0005[חזר\u0006 ו\u0005שנה אותו].\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"ולקח\u0004 הכהן מדם האשם\" (ויקרא יד, יד) — \u0003יכול\u0004 יקח את הדם הזה \u0003בכלי? תלמוד לומר\u0004 מיד אחר כך: \u0003\"ונתן\u0004 הכהן על תנוך אוזן המיטהר וגו'\" (ויקרא יד, יד), \u0003מה נתינה בעצמו\u0004 (בגופו) \u0003של כהן\u0004 שנותן את הדם באצבעו, וכפי שלמדו מנתינת השמן על המצורע — \u0003אף לקיחה\u0004 של הדם, קבלתו, \u0003בעצמו של כהן.\u0004","\u0003יכול אף למזבח כן?\u0004 כלומר, שאף לצורך זריקת הדם על המזבח יקח את הדם בידו? \u0003תלמוד לומר: \"כי כחטאת האשם הוא\"\u0004 (ויקרא יד, יג), ללמד: \u0003מה חטאת טעונה כלי\u0004 לקבלה, \u0003אף אשם טעון כלי. נמצאת אתה אומר: אשם מצורע שני כהנים מקבלין את דמו, אחד\u0004 מקבל \u0003ביד ואחד בכלי, זה שקיבלו בכלי בא לו אצל מזבח\u0004 ומזה, \u0003וזה שקיבלו ביד בא לו אצל מצורע\u0004 ונותן מן הדם על תנוך אוזנו ועל בהונותיו."],["שנינו במשנה: קדשי קדשים שחיטתן בצפון, ובפירוט הדברים שנינו תחילה: \u0003פר ושעיר של יום הכיפורים\u0004 שחיטתן בצפון כו'. ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 דין שחיטה ב\u0003צפון בעולה כתיב\u0004 \u0005[נאמר],\u0006 ואינו מפורש באחרים, ואם כן, \u0003ניתני\u0004 \u0005[שישנה]\u0006 \u0003עולה ברישא\u0004 \u0005[בראש]!\u0006","ומשיבים: דין צפון ב\u0003חטאת, איידי דאתי\u0004 \u0005[מתוך ש\u0006הוא \u0005בא\u0006 נלמד\u0005]\u0006 \u0003מדרשא\u0004 מן ההיקש לעולה, ואין הדבר מפורש בה, \u0003חביבא ליה\u0004 \u0005[חביב לו]\u0006 לתנא, והקדימו.","ושואלים: \u0003וניתני\u0004 \u0005[ושישנה]\u0006 תחילה \u0003חטאות החיצונות,\u0004 שהרי בהן נזכרת ההשוואה לעולה! ומשיבים: חטאות הפנימיות, \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003נכנס דמן לפני ולפנים חביבא ליה\u0004 \u0005[חביבות עליו]\u0006 והקדימן.","ושואלים: \u0003וצפונה\u0004 \u0003בעולה היכא כתיבא\u0004 \u0005[היכן\u0006 היא \u0005כתובה]?\u0006 ומשיבים, שנאמר בעולה הבאה מן הצאן: \u0003\"ושחט אתו על\u0004 \u0003ירך המזבח צפנה\"\u0004 (ויקרא א, יא).","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 דין זה\u0005]\u0006 בשחיטת \u0003בן צאן, בן בקר מנא לן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בתחילת פרשיה זו: \u0003\"ואם\u0004 \u0003מן הצאן\"\u0004 (ויקרא א, י), \u0003וי\"ו\u0004 של \"ואם\" \u0003מוסיף\u0004 את האמור בפרשה \u0003זו\u0004 \u0003על ענין ראשון\u0004 על הפרשיה הקודמת, בענין עולה מן הבקר, \u0003ו\u0004בדרך זו \u0003ילמד עליון\u0004 בן בקר \u0003מתחתון\u0004 בן צאן.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שבאופן זה \u0003מלמדין\u0004 מתחתון לעליון, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אין מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כך \u0005שנויה\u0006 ברייתא\u0005]:\u0006 מיד לאחר פרשת אשם מעילות (שמביא אדם שמעל בהקדש בשגגה), נאמר בראש פרשת אשם תלוי (שמביא אדם שספק חטאת בידו): \u0003\"ואם נפש\"\u0004 (ויקרא ה, יז) — הרי זה בא \u0003לחייב על ספק מעילות אשם תלוי,\u0004 אלו \u0003דברי ר' עקיבא, וחכמים פוטרין. מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003למידין\u0004 עליון (פרשת אשם מעילות) מתחתון (אשם תלוי), שגם לגביה קיים דין זה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003אין למידין?\u0004","\u0003אמר רב פפא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003למידין, והיינו טעמא דרבנן\u0004 \u0005[וזהו הטעם של חכמים],\u0006 שפוטרים ספק מעילה מאשם תלוי, לדעתם יש גזירה שווה הסותרת דין זה: \u0003נאמר כאן\u0004 באשם תלוי \u0003\"מצו‍ת\"\u0004 (\"ועשתה אחת מכל מצוות ה' אשר לא תעשינה\" ויקרא ה, יז) \u0003ונאמר בחטאת חלב\u0004 כלומר, בחטאת רגילה שאדם מביא על שגגתו \u0003\"מצו‍ת\"\u0004 (\"בעשותה אחת ממצוות ה' אשר לא תעשינה\" ויקרא ד, כז),","\u0003מה להלן\u0004 בחטאת, מביא קרבן רק על \u0003דבר שחייבין על זדונו כרת ועל שגגתו חטאת, אף כאן\u0004 אשם תלוי, מביא על דבר \u0003שחייבין על זדונו כרת ועל שגגתו חטאת,\u0004 ומעילה אינה בכלל זה.","ושואלים: \u0003ור' עקיבא\u0004 מה הוא למד מגזירה שווה זו? ומסבירים: \u0003מה להלן\u0004 כשנאמר \"מצות\" מדובר \u0003ב\u0004חטאת \u0003קבועה, אף כאן\u0004 לענין אשם תלוי, מדובר \u0003ב\u0004ספק של חטאת \u0003קבועה, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003חטאת\u0004 של \u0003טומאת מקדש וקדשיו,\u0004 שקרבן \u0003עולה ויורד הוא\u0004 לפי עושרו של החוטא, שאם דל הוא מביא קרבן עוף או מנחה, ובזה אינו מביא אשם תלוי על הספק. אבל אין מדובר דווקא על עבירה שעונשה כרת.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003אין גזירה שוה למחצה,\u0004 ואם הושווה אשם תלוי לחטאת — הושווה לכל דבר, ואף להגדרת העבירה עליה הוא בא, שהיא בכרת. ושואלים: \u0003ור' עקיבא נמי\u0004 \u0005[גם כן],\u0006 מה הוא טוען? הרי \u0003אין גזירה שוה למחצה!\u0004","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן כך\u0006 הוא \u0005גם כן]\u0006 לדעתו, \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003\"ואם נפש\"\u0004 (ויקרא ה, יז) \u0003כתיב\u0004 \u0005[נאמר]\u0006 באשם תלוי, \u0003וי\"ו מוסיף על ענין ראשון\u0004 וילמד עליון מתחתון, ולכן גם על ספק מעילה מביא אשם תלוי.","ושואלים: \u0003ורבנן נמי\u0004 \u0005[וחכמים גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ואם נפש\"! לימא בהא קמיפלגי\u0004 \u0005[האם לומר שב\u0006נושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006, ר' עקיבא, \u0005סבור]:\u0006 \u0003היקש\u0004 (סמיכות הכתובים) \u0003עדיף\u0004 על הגזירה שווה, ולכן מביאים גם על ספק מעילה אשם תלוי, \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003גזירה שוה עדיף\u0004 ולכן אשם תלוי בא רק על עבירה שעונשה כרת?","ומשיבים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003היקש עדיף, ו\u0004מדוע לדעת חכמים אין מביאים אשם תלוי על ספק מעילה? על כך \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003לך רבנן\u0004 \u0005[חכמים]:\u0006 אמנם הולכים אנו כאן אחר היקש, אבל לא העליון נלמד מן התחתון, אלא \u0003תחתון\u0004 (אשם תלוי) \u0003הוא דגמר\u0004 \u0005[שלומד]\u0006 \u0003מעליון\u0004 (אשם מעילות),","\u0003ל\u0004ענין זה ש\u0003אשם\u0004 תלוי דינו \u0003ב\u0004איל שערכו \u0003כסף שקלים\u0004 (לפחות שני שקלים). \u0003שלא תאמר: לא יהא ספיקו\u0004 אשם תלוי שמביא על ספק עבירה שיש בה חטאת, \u0003חמור מודאו\u0004 מחטאת שמביא על עבירה שעבר עליה בוודאות, \u0003מה ודאו\u0004 מביא עליו \u0003חטאת\u0004 אפילו \u0003בת דנקא\u0004 \u0005[שישית הדינר],\u0006 \u0003אף ספיקו\u0004 לא יביא אלא \u0003אשם בר דנקא\u0004 \u0005[בן שישית הדינר].\u0006","ושואלים: \u0003ור' עקיבא הא סברא מנא ליה\u0004 \u0005[סברה זו מנין לו]\u0006 מנין הוא יודע שאשם תלוי הוא בכסף שקלים? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת לו, נלמדת]\u0006 \u0003מ\u0004מה שנאמר \u0003\"זאת תורת האשם\"\u0004 (ויקרא ז, א), לומר: \u0003תורה אחת לכל האשמות,\u0004 וכולם באים בכסף שקלים.","ושואלים: \u0003תינח מאן דאית ליה\u0004 \u0005[זה נוח\u0006 ל\u0005מי שיש\u0006 לו, מקבל] לימוד זה של \u0003\"תורת\", מאן דלית ליה\u0004 \u0005[מי שאין לו,\u0006 שאינו \u0005מקבל\u0006\u0005]\u0006 לימוד זה של \u0003\"תורת\" מהיכא גמר\u0004 \u0005[מהיכן\u0006 הוא \u0005למד]\u0006 לשאר אשמות? ומשיבים: \u0003גמר\u0004 \u0005[למד\u0006 הוא\u0005]\u0006 מגזירה שווה של \u0003\"בערכך\u0004 כסף שקלים\" (ויקרא ה, טו) ל\u0003\"בערכך\"\u0004 האמור באשמות אחרים (ויקרא ה, יח. ויקרא ה, כה).","ושואלים: \u0003תינח היכא דכתיב\u0004 \u0005[נניח במקום שנאמר]\u0006 במפורש \u0003\"בערכך\",\u0004 והוא באשם תלוי ואשם גזילות, \u0003אשם שפחה חרופה\u0004 ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"בערכך\", מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה מ\u0003\"באיל\u0004 האשם\" (ויקרא ה, טז) האמור באשם מעילות, שנאמר בו כסף שקלים, ו\u0003\"באיל\u0004 האשם\" (ויקרא יט, כב) האמור בדין שפחה חרופה.","ושבים לעיקרו של הדיון, ושואלים: \u0003חטאת מנא לן דבעיא\u0004 \u0005[מנין לנו שצריכה]\u0006 \u0003צפון?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בחטאת היחיד: \u0003\"ושחט את החטאת במקום העולה\"\u0004 (ויקרא ד, כט), וכשם שהעולה בצפון, כפי שנתבאר לעיל, כך חטאת בצפון.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה לגבי \u0003שחיטה, קבלה\u0004 של הדם \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שתהא בצפון? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 מיד אחר כך: \u0003\"ולקח הכהן מדם החטאת\"\u0004 (ויקרא ד, לד), והוא בהכרח במקום השחיטה, שהרי צריך לקבל את הדם מצואר הבהמה.","ושואלים: \u0003מקבל עצמו מנא לן\u0004 \u0005[מנין לנו]\u0006 שהוא צריך להיות בצפון? ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ולקח\"\u0004 — \u0003\"לו יקח\",\u0004 שמשנים את סדר האותיות במלה \"ולקח\" כאילו כתוב שיקח את עצמו.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין שחיטה בצפון \u0003למצוה, לעכב מנין?\u0004 ומשיבים: \u0003קרא אחרינא כתיב\u0004 \u0005[מקרא אחר כתוב]\u0006 בשעיר נשיא, שאף הוא חטאת: \u0003\"ושחט אותו במקום אשר ישחט את העולה\"\u0004 (ויקרא ד, כד), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 על כתוב זה: \u0003היכן עולה נשחטה? בצפון, אף זה\u0004 החטאת \u0003בצפון.\u0004"],["ויש לשאול: \u0003וכי מכאן אתה למד? והלא כבר נאמר\u0004 באופן כללי, לגבי החטאות כולן: \"זאת תורת החטאת \u0003במקום אשר תשחט העולה תשחט החטאת\"\u0004 (ויקרא ו, יח)! אלא \u0003הא ל\u0004שם \u0003מה יצא\u0004 ונאמר הדבר בשעיר הנשיא? \u0003לקבוע לו מקום\u0004 זה בלבד, \u0003שאם לא שחטה בצפון\u0004 — \u0003פסול\u0004 אפילו בדיעבד.","ושואלים: \u0003אתה אומר לכך יצא, או אינו\u0004 בא \u0003אלא\u0004 להדגיש: \"ושחט אותו\", לומר \u0003ש\u0004רק שעיר חטאת \u0003זה\u0004 של נשיא \u0003טעון צפון ואין\u0004 שעיר \u0003אחר טעון צפון? תלמוד לומר\u0004 בשעירת חטאת של יחיד: \u0003\"ושחט את החטאת במקום העולה\"\u0004 (ויקרא ד, כט) \u0003זה בנה אב\u0004 מכאן לימדה התורה \u0003לכל חטאות שיהו טעונות צפון,\u0004 ואם כן נאמר בשעיר נשיא דין צפון לומר שהוא לעיכוב. עד כאן הברייתא בענין שעיר נשיא.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 אפוא כתוב לגבי \u0003שעיר נשיא בין למצוה בין לעכב,\u0004 וכן ב\u0003שאר חטאות נמי אשכחן\u0004 \u0005[גם כן מצאנו]\u0006 דין זה \u0003למצוה, לעכב מנא לן\u0004 \u0005[מנין לנו]?\u0006","ומשיבים: מתוך \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 דין שחיטת צפון \u0003בכשבה\u0004 של חטאת (ויקרא ד, לג) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 גם \u0003בשעירה\u0004 של חטאת (ויקרא ד, כט).","ושבים לדון בברייתא, ושואלים: כיון שלמדנו שכל החטאות כולן צריכות להישחט בצפון, \u0003אלא \"אתו\"\u0004 האמור בשעיר נשיא (ויקרא ד, כד) \u0003למה לי?\u0004 והרי אין ממעטים ממנו שעירים אחרים!","ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אותו בצפון,\u0004 \u0003ואין שעיר נחשון\u0004 נשחט \u0003בצפון\u0004 כלומר, שעיר החטאת שהקריב נחשון נשיא שבט יהודה (ושאר הנשיאים) בחנוכת המשכן, שהובא כמתנה ולא כדי לכפר על חטא, ללמד שאין דינו כשאר חטאות, ואינו טעון סמיכה.","\u0003ו\u0004מדוע יש כלל צורך במיעוט זה? כי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת בענין שעיר נשיא, שנאמר: \u0003\"וסמך ידו על ראש השעיר\"\u0004 (ויקרא ד, כד) ויכול היה לומר \"על ראשו\", שהרי מדובר שם על השעיר, אלא בא \u0003לרבות שעיר נחשון לסמיכה,\u0004 אלו \u0003דברי ר' יהודה. ר' שמעון אומר: לרבות שעירי עבודה זרה לסמיכה,\u0004 שלא הוזכרה בו.","ומעתה, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיתרבו\u0004 \u0005[ו\u0006לשיטת ר' יהודה \u0005התרבו]\u0006 בפסוק זה שעירי חטאות הנשיאים \u0003לסמיכה\u0004 — \u0003איתרבו נמי\u0004 \u0005[התרבו גם כן]\u0006 שיצטרכו לשוחטם \u0003לצפון, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה, ל\u0004שיטת \u0003ר' שמעון,\u0004 שלא ריבה שעיר נחשון לסמיכה מן האמור בשעיר נשיא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב טבי לרבינא: ולר' יהודה,\u0004 שריבה סמיכה בשעיר נחשון, \u0003מי ניחא\u0004 \u0005[האם\u0006 זה \u0005נוח]?\u0006 מדוע בגלל ריבוי זה צריך למעט שעיר נחשון משחיטה בצפון? הרי בפשטות יש לומר: \u0003למאי דאיתרבי איתרבי\u0004 \u0005[למה שהתרבה התרבה]\u0006 לענין סמיכה, \u0003ומאי\u0004 \u0005[ומה]\u0006 ש\u0003לא איתרבי\u0004 \u0005[התרבה]\u0006 \u0003לא איתרבי\u0004 \u0005[התרבה]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין זה בגלל הריבוי לענין סמיכה, אלא \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא מעטיה קרא\u0004 \u0005[היה המקרא ממעט אותו]\u0006 את שעיר נחשון משחיטת צפון, \u0003הוה אמינא תיתי\u0004 \u0005[הייתי אומר שיבוא,\u0006 יילמד\u0005]\u0006 \u0003בבנין אב\u0004 ככל חטאת — דבר זה לא ייתכן, כי \u0003אם כן,\u0004 ששעיר נחשון בכלל כל החטאות הוא, \u0003סמיכה גופה\u0004 \u0005[עצמה]\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 \u0003מבנין אב,\u0004 ומדוע נלמדה מריבוי הכתובים? \u0003אלא\u0004 טעם הדבר הוא ש\u0003מ\u0004קרבן של \u0003דורות לא גמרינן\u0004 \u0005[למדים אנו]\u0006 בבנין אב לקרבן הנשיאים שהיה רק לשעתו\u0005, ולכן הוצרכנו לריבוי לענין סמיכה. ולפי זה\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לענין שחיטת צפון, \u0003מדורות לא גמרינן\u0004 \u0005[למדים אנו],\u0006 ואם כן, לא הוצרכנו כלל למעט שעיר נחשון מדין זה!","\u0003ואלא\u0004 \"ושחט אותו בצפון\" מה הוא בא למעט? לומר: \u0003אותו בצפון ואין שוחט\u0004 חייב להיות \u0003בצפון.\u0004","ומקשים: דינו של \u0003שוחט מ\u0004דברי \u0003ר' אחיא נפקא\u0004 \u0005[יוצא]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אחיא אומר: \"ושחט אתו על ירך המזבח צפונה\"\u0004 האמור בקרבן עולה (ויקרא א, יא) — \u0003מה תלמוד לומר\u0004 \"אותו\"?","\u0003לפי שמצינו\u0004 שהכהן \u0003עומד בצפון ומקבל בצפון, ואם עמד בדרום וקיבל בצפון פסול, יכול אף זה\u0004 השוחט יהא דינו \u0003כן?\u0004 \u0003תלמוד לומר \"אתו\u0004 על ירך המזבח צפונה\", \u0003אותו\u0004 הקרבן \u0003בצפון ואין השוחט\u0004 עצמו חייב להיות \u0003בצפון!\u0004","\u0003אלא\u0004 כך צריך ללמוד מ\"אותו\" האמור בשעיר נשיא: \u0003אותו בצפון ואין\u0004 מליקת \u0003בן עוף\u0004 צריכה להיות \u0003בצפון. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על אותו פסוק האמור בעולה מן הצאן \"ושחט אותו על ירך המזבח צפונה\" (ויקרא א, יא): \u0003יכול יהא בן עוף טעון צפון? ודין הוא: ומה בן צאן שלא קבע לו כהן\u0004 שישחטנו, אלא כל אדם יכול לעשות זאת (ראה לעיל זבחים לב,א) — \u0003קבע לו צפון, בן עוף שקבע לו כהן\u0004 שרק כהן הוא המולק אותו — \u0003אינו דין שיקבע לו צפון? תלמוד לומר \"אתו\"\u0004 למעט בן עוף.","ומקשים: והרי אין כאן כלל קל וחומר, שנצטרך למעטו מ\"אותו\", כי \u0003מה לבן צאן\u0004 שהוא חמור מעוף — \u0003שכן קבע לו\u0004 הכתוב \u0003כלי\u0004 לשחיטתו, ועוף נמלק בציפורנו של הכהן!","\u0003אלא\u0004 כך מדייקים מ\"אותו\": \u0003אותו\u0004 שעיר נשיא נשחט \u0003בצפון ואין פסח\u0004 נשחט \u0003בצפון.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 נוספת לגבי \"אותו\" האמור בקרבן עולה (לעיל זבחים לב,א), \u0003ר' אליעזר בן יעקב אומר: יכול יהא פסח טעון צפון? ו\u0004לכאורה \u0003דין הוא: ומה עולה שכן לא קבע לו זמן לשחיטתו\u0004 בכל זאת \u0003קבע לו צפון, פסח שקבע לו זמן לשחיטתו\u0004 בארבעה עשר בניסן \u0003אינו דין שיקבע לו צפון? תלמוד לומר \"אתו\"\u0004 למעט את הפסח.","ומקשים: והרי אין כאן קל וחומר, כי \u0003מה לעולה שכן\u0004 היא עולה \u0003כליל,\u0004 וקרבן פסח נאכל!","ומציעים: מכל מקום ניתן ללמוד קל וחומר לפסח \u0003מחטאת\u0004 שאין לה זמן קבוע, ואינה כליל, ושחיטתה בצפון. ודוחים גם קל וחומר זה: \u0003מה לחטאת שכן מכפרת על חייבי כריתות!\u0004","ומציעים: נלמד \u0003מאשם.\u0004 ודוחים: \u0003מה לאשם שכן קדשי קדשים!\u0004 ומוסיפים: \u0003מכולן נמי\u0004 \u0005[גם כן],\u0006 מעולה וחטאת, אי אפשר ללמוד, \u0003שכן\u0004 כולם \u0003קדשי קדשים!\u0004 אם כן חוזרת השאלה למקומה: מה למדנו מ\"אותו\"?","ומשיבים: \u0003לעולם\u0004 יש לומר \u0003כדאמרן מעיקרא\u0004 \u0005[כמו שאמרנו מתחילה]:\u0006 \u0003אותו בצפון ואין שוחט בצפון. ודקשיא לך\u0004 \u0005[ו\u0006מה \u0005שהיה קשה לך]:\u0006 הרי דבר זה \u0003מ\u0004דברי \u0003ר' אחיא\u0004 לענין עולה \u0003נפקא לן\u0004 \u0005[יוצא לנו]!\u0006 על כך יש להשיב: \"אותו\" האמור בשעיר \u0003לאו למעוטי\u0004 \u0005[לא למעט]\u0006 \u0003שוחט בצפון\u0004 הוא בא, כפי שדרש ר' אחיא מ\"אותו\" שבעולה, \u0003אלא\u0004 להוסיף וללמוד ממיעוט זה דבר נוסף: \u0003אין שוחט\u0004 צריך להיות \u0003בצפון\u0004 — \u0003אבל מקבל\u0004 הדם צריך להיות \u0003בצפון.\u0004","ושואלים: הלוא \u0003מקבל\u0004 שצריך להיות בצפון, \u0003מ\u0004מה שיכול היה לכתוב \u0003\"לקח\"\u0004 וכתב \u0003\"ולקח\" נפקא\u0004 \u0005[יוצא],\u0006 כפי שלמדנו בעמוד הקודם, כאילו נאמר \"לו יקח\"! ומשיבים: הלימוד הזה של \u0003\"לקח\" \"ולקח\" לא משמע ליה\u0004 \u0005[אינו נשמע לו]\u0006 כלומר, אין החכם שבברייתא בענין שעיר מקבל אותו.","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור לכך ש\u0003שחיטה בעולה\u0004 בצפון \u0003למצוה,\u0004 כפי שהתבאר בסוף העמוד הקודם, \u0003קבלה\u0004 בעולה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003למצוה אשכחן\u0004 \u0005[מצאנו]\u0006 כמבואר שם, אולם \u0003שחיטה וקבלה\u0004 בצפון \u0003לעכב מנלן\u0004 \u0005[מנין לנו]?\u0006 מנין שאם לא שחט עולה או קיבל דמה בצפון הרי היא פסולה?","\u0003אמר רב אדא בר אהבה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר שילא: קל וחומר, ומה חטאת הבאה מכח עולה\u0004 שהרי נאמר \"ושחט את החטאת במקום העולה\" \u0003מעכבת,\u0004 כפי שלמדנו בראש עמוד זה ממה ששנה בה הכתוב דין צפון — \u0003עולה שבאה חטאת מכחה אינו דין שמעכבת?\u0004","ודוחים: אין להוכיח מכאן, כי \u0003מה לחטאת\u0004 שיש בה חומרה יתירה, \u0003שכן מכפרת על חייבי כריתות!\u0004","\u0003אמר רבינא, הא קשיא ליה\u0004 \u0005[זה היה קשה לו]\u0006 \u0003לרב אדא בר אהבה: כלום מצינו טפל חמור מן העיקר?\u0004 שהרי העיקר הוא העולה, והחטאת נלמדת ממנה, וכיצד יהא הדבר הנלמד חמור יותר מאשר מקורו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: ולא\u0004 מצאנו דבר כגון זה?"],["\u0003והרי מעשר\u0004 שני יוכיח שכן, ש\u0003הוא\u0004 עצמו \u0003נפדה\u0004 יש אפשרות לפדות אותו בכסף, ולהעלות את הכסף לירושלים כדי לקנות בו שם דברי מאכל, \u0003ואילו לקוח בכסף מעשר\u0004 (כשפודים מעשר שני וקונים בדמיו בפירות אחרים) שבא מכוחו \u0003אינו נפדה,\u0004 אלא נאכל בירושלים! \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הלקוח בכסף מעשר שנטמא\u0004 — \u0003יפדה, ר' יהודה אומר: יקבר.\u0004 ויש לדייק בדברי המשנה: \u0003נטמא\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 ניתן לפדותו, \u0003לא נטמא\u0004 — \u0003לא\u0004 ייפדה. משמע שהטפל (לקוח בכסף מעשר) חמור מן העיקר (מעשר עצמו) שאינו נפדה כשהוא טמא!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 טעם הדבר שאינו נפדה אינו חומרה שיש בו, אלא משום ש\u0003לא אלימא קדושתיה למיתפס פדיוניה\u0004 \u0005[אין קדושתו חזקה\u0006 דיה כדי \u0005לתפוס\u0006 את \u0005פדיונו].\u0006","וחוזרים ומקשים: \u0003והרי תמורה,\u0004 שאדם אומר על בהמה שתהא קדושה תמורת בהמת קדשים, וקדושה חלה עליה, הרי היא באה מכח קדשים, והיא חמורה מהם, ש\u0003אילו קדשים לא חיילי\u0004 \u0005[אינם חלים]\u0006 \u0003על\u0004 \u0003בעל מום קבוע\u0004 אם הקדיש בהמה בעלת מום קבוע — אינה קדושה קדושת הגוף, ואם נפדית — הריהי בהמת חולין. \u0003ואילו איהי חיילא\u0004 \u0005[היא,\u0006 התמורה \u0005חלה]\u0006 שאם המיר בהמת קדשים בבהמת חולין — חלה עליה קדושת הגוף גם אם היתה בעלת מום, ואף שהיא נפדית — אסור לעבוד בה וליהנות מצמרה, אלא רק לאוכלה!","ומשיבים: גם כאן אין זו חומרה שיש בתמורה עצמה, אלא משום ש\u0003תמורה מכח קדשים\u0004 שיש בהם קדושת הגוף \u0003קא אתיא\u0004 \u0005[היא באה],\u0006 לכן יכול להחיל את קדושתם אף על בעל מום, \u0003ו\u0004אילו \u0003קדשים\u0004 שמקדיש אדם בהמה מתחילה — הרי \u0003מכח חולין קאתי\u0004 \u0005[הם באים],\u0006 ואין אפשרות להקדיש מתחילה בהמת חולין בעלת מום, שתהא קדושה קדושת הגוף. עוד מקשים: וכי אין טפל שחמור מן העיקר למרות שבא מכוחו?","ו\u0003הרי פסח,\u0004 ש\u0003הוא אינו טעון\u0004 \u0003סמיכה ונסכים ותנופת חזה ושוק, ואילו מותר דידיה\u0004 \u0005[שלו]\u0006 כבש שהוקדש לשם פסח ולא הוקרב בשעתו חמור ממנו, שהוא \u0003טעון סמיכה ונסכים ותנופת חזה\u0004 \u0003ושוק!\u0004","ומשיבים: \u0003פסח בשאר ימות השנה\u0004 אינו קרוי כלל מותר פסח, אלא \u0003שלמים הוא,\u0004 ויש לו דין שלמים לכל דבר וענין. ונמצא למסקנה כי הסברה שלא יהא טפל חמור מן העיקר — סברה טובה היא, ויש ללמוד על ידה שגם בעולה, כמו בחטאת הטפלה לה, דין שחיטה וקבלת הדם בצפון הריהו לעיכוב.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הוכחה אחרת שעולה בצפון היא לעכב, ממה ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 כמה פעמים: \"במקום... \u0003העולה\"\u0004 (ויקרא ד, כד. ויקרא ד, כט. ויקרא ד, לג) להדגיש כי העולה \u0003במקומה תהא,\u0004 והיא פסולה בכל מקום אחר.","ושואלים עוד: \u0003אשם,\u0004 שגם הוא בכלל קדשי קדשים, \u0003מנלן דבעי\u0004 \u0005[מנין לנו ש\u0006הוא \u0005צריך]\u0006 \u0003צפון?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במקום אשר ישחטו את העלה ישחטו את האשם\"\u0004 (ויקרא ז, ב), ובעולה נאמר: \"ושחט אותו על ירך המזבח צפונה\" (ויקרא א, יא).","ועוד שואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין \u0003שחיטה\u0004 באשם בצפון, \u0003קבלה מנא לן\u0004 \u0005[מנין לנו]\u0006 שהיא בצפון? ומשיבים, שנאמר מיד לאחר מכן: \u0003\"ואת דמו יזרוק\"\u0004 (ויקרא ז, ב), וכיון שהקבלה סמוכה לשחיטה קודם הזריקה, הריהי נרמזת בביטוי \"ואת דמו\", ונמצא כי \u0003קבול דמו נמי\u0004 \u0005[גם כן]\u0006 \u0003בצפון.\u0004","ושואלים: \u0003מקבל עצמו מנא לן\u0004 \u0005[מנין לנו]\u0006 שהוא צריך לעמוד בצפון? ומשיבים: משום שלא נאמר רק \u0003\"דמו\u0004 יזרוק\" — אלא \u0003\"ואת דמו\"\u0004 הרי \"את\" זה ריבוי גם למקבל.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 שיש \u0003מצוה\u0004 לשחוט את האשם בצפון, \u0003לעכב מנא לן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003קרא אחרינא כתיב\u0004 \u0005[מקרא אחר כתוב]\u0006 באשם מצורע: \u0003\"ושחט את הכבש\u0004 במקום אשר ישחט את החטאת ואת העולה\" (ויקרא יד, יג), ומשם אנו למדים לשאר אשמות.","ושואלים: \u0003והאי להכי הוא דאתא\u0004 \u0005[ו\u0006כתוב \u0005זה לכך הוא שבא]?\u0006 \u0003האי מיבעי\u0004 \u0003ליה לכדתניא\u0004 \u0005[זה נצרך לו לכמו ששנויה]\u0006 בברייתא, בביאור המדות שהתורה נדרשת בהן: \u0003דבר שהיה\u0004 \u0003בכלל ויצא לידון בדבר החדש, אי אתה רשאי להחזירו לכללו\u0004 \u0003עד שיחזירנו הכתוב לכללו בפירוש,\u0004","\u0003כיצד?\u0004 נאמר: \u0003\"ושחט את\u0004 \u0003הכבש במקום אשר ישחט את החטאת ואת העולה במקום\u0004 \u0003הקדש כי כחטאת האשם הוא\"\u0004 (ויקרא יד, יג), \u0003שאין תלמוד\u0004 (צורך) \u0003לומר \"כחטאת האשם\u0004 הוא\", שהרי כבר הושווה בפסוק זה האשם לחטאת, \u0003מה תלמוד לומר\u0004 בכל זאת \u0003\"כחטאת האשם\"?\u0004","\u0003לפי שיצא אשם מצורע\u0004 מכלל האשמות \u0003לידון בדבר החדש,\u0004 שנותנים מדמו \u0003בבוהן יד ובוהן רגל ואזן ימנית\u0004 של המצורע, שמא איננו עוד בכלל האשמות, ואם כן \u0003יכול לא יהא טעון\u0004 כלל \u0003מתן דמים ואימורין לגבי מזבח?\u0004","\u0003תלמוד לומר: \"כחטאת האשם הוא\",\u0004 ללמד: \u0003מה חטאת טעונה מתן דמים ואימורין לגבי מזבח, אף אשם מצורע,\u0004 למרות שאין הדבר מפורש בו כאן, \u0003טעון מתן דמים ואימורין לגבי מזבח.\u0004 וכדרך שהוצרך הכתוב להטעין אשם מצורע במתן דמים ואימורים, כך הוצרך \"ושחט את הכבש\" בפסוק זה להטעינו שחיטה בצפון. ואם כן אין הוא מיותר כדי ללמוד ממנו לעכב בכל האשמות!","ומשיבים: \u0003אם כן,\u0004 ששחיטת צפון אינה אלא למצוה בכל האשמות, \u0003נכתוב בהאי\u0004 \u0005[שיכתוב\u0006 שחיטת צפון \u0005בזה]\u0006 באשם מצורע, \u0003ולא נכתוב בהאי\u0004 \u0005[יכתוב\u0006 שחיטת צפון \u0005בזה]\u0006 בדין אשם בכלל, ויילמדו כל האשמות מאשם מצורע. אלא יש כאן יתור המלמד לעכב.","ומקשים: \u0003הניחא אי\u0004 \u0003סבירא לן\u0004 \u0005[זה נוח אם סבורים אנו]:\u0006 כי דבר ש\u0003יצא לידון בדבר החדש,\u0004 \u0003איהו הוא דלא גמר\u0004 \u0005[\u0006שדווקא \u0005הוא שאינו למד]\u0006 \u0003מכללו,\u0004"],["\u0003אבל כללו גמר מיניה\u0004 \u0005[למד ממנו]\u0006 — \u0003שפיר\u0004 \u0005[יפה],\u0006 שלדעתו ניתן ללמוד דין שחיטת צפון מאשם תלוי לשאר אשמות, והכתוב האחר מלמד שהוא לעכב. \u0003אלא אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 שפרט שיצא לידון בדבר החדש \u0003לא הוא גמר\u0004 \u0005[למד]\u0006 \u0003מכללו ולא כללו גמר מיניה\u0004 \u0005[למד ממנו],\u0006 \u0003האי לגופיה איצטריך\u0004 \u0005[זה,\u0006 כל אחד מהם, \u0005לגופו הוצרך]!\u0006","ומשיבים: \u0003כיון דאהדריה\u0004 \u0005[ש\u0006בפסוק זה \u0005החזירו\u0006 הכתוב\u0005]\u0006 את אשם המצורע לכלל האשמות, \u0003אהדריה\u0004 \u0005[החזירו]\u0006 לכל ענין, ואף לשחיטת צפון, ונמצא שמה שהוזכרה במפורש שחיטת צפון בפסוק זה (\"ושחט את הכבש במקום\" וכו') אינו נצרך לגופו, ולא הוזכר אלא כדי לעכב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא, אימא\u0004 \u0005[אמור]:\u0006 \u0003כי אהדריה קרא\u0004 \u0005[כאשר החזיר אותו המקרא]\u0006 את אשם מצורע, שיהא כשאר אשמות, הרי זה דווקא \u0003לגבי מתן דמים ו\u0004הקטרת \u0003אימורין, דבעי\u0004 \u0005[שצריך\u0006 בהם\u0005]\u0006 \u0003כהונה,\u0004 כלשון הכתוב שם: \"כי כחטאת האשם הוא לכהן\" (ויקרא יד, יג), \u0003אבל שחיטה, דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 \u0003כהונה לא מיבעי\u0004 \u0005[תצטרך]\u0006 \u0003צפון!\u0004 והשיב לו: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר המקרא]\u0006 \u0003\"כי כחטאת הוא\", מאי\u0004 \u0005[מהו]\u0006 \u0003\"כחטאת האשם\u0004 הוא\"? לומר ש\u0003כשאר אשמות יהיה\u0004 אף לשחיטה, שתהא בצפון.","","ושואלים: \u0003למה לי לאקשויי\u0004 \u0005[להקישו]\u0006 את האשם \u0003לחטאת, למה לי לאקשויי\u0004 \u0005[להקישו]\u0006 \u0003לעולה\u0004 (\"במקום אשר ישחט את החטאת ואת העולה\". ויקרא יד, יג)? מה צורך להשוותו לשניהם?","\u0003אמר רבינא: איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 כי \u0003אי\u0004 \u0003אקשיה\u0004 \u0005[אם היה מקיש אותו]\u0006 \u0003לחטאת ולא אקשיה\u0004 \u0005[היה מקיש אותו]\u0006 \u0003לעולה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חטאת מהיכן למדה\u0004 ששחיטתה בצפון? \u0003מ\u0004היקש ל\u0003עולה,\u0004 והייתי לומד מתוך כך כלל שגוי במדרש ההלכה, כי \u0003דבר הלמד בהיקש חוזר ומלמד בהיקש.\u0004 לכך הוצרך גם ההיקש לעולה\u0003.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: וניקשיה\u0004 \u0005[ושיקיש אותו]\u0006 רק \u0003לעולה ולא ניקשיה\u0004 \u0005[יקיש אותו]\u0006 \u0003לחטאת!\u0004 ומשיבים: אם כך, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי בכלל \u0003דבר הלמד בהיקש חוזר ומלמד בהיקש. וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 אם כן הוא, \u0003ניקשי אקושי\u0004 \u0005[שיקיש\u0006 את האשם\u0005]\u0006 \u0003לחטאת,\u0004 ניתן היה להשיב על כך: \u0003ניחא ליה דמקיש ליה\u0004 \u0005[נוח לו להקיש אותו]\u0006 \u0003לעיקר\u0004 (שהוא העולה) \u0003ולא נקיש ליה\u0004 \u0005[נקיש אותו]\u0006 \u0003לטפל\u0004 (החטאת), \u0003להכי אקשיה\u0004 \u0005[\u0006משום \u0005כך הקיש אותו]\u0006 \u0003לחטאת\u0004 \u0003ו\u0004גם \u0003אקשיה\u0004 \u0005[הקיש אותו]\u0006 \u0003לעולה, למימר\u0004 \u0005[לומר]\u0006 ללמוד מכאן כי \u0003דבר הלמד בהיקש שאינו חוזר ומלמד בהיקש.\u0004","","","\u0003רבא אמר:\u0004 למדים כלל מדרש זה \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפר כהן משיח, שמרימים את אימוריו ממנו: \u0003\"כאשר יורם משור זבח השלמים\"\u0004 (ויקרא ד, י), ויש לשאול: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ליותרת הכבד ושתי הכליות\u0004 שמרימים ממנו — \u0003בגופיה כתיב\u0004 \u0005[בגופו כתוב]\u0006 (ויקרא ד, ט), ואינו צריך ללמוד מההיקש!","\u0003אמר רב פפא: משום דבעי אגמורי\u0004 \u0005[ש\u0006הוא \u0005רוצה ללמד]\u0006 על \u0003יותרת הכבד ושתי הכליות מפר העלם דבר של צבור לשעירי עבודה זרה,\u0004 אבל \u0003בגופיה לא כתיב\u0004 \u0005[בגופו\u0006 של פר העלם דבר \u0005לא נאמר]\u0006 דין זה, \u0003ומפר כהן משיח הוא דגמר\u0004 \u0005[שלמד]\u0006 לפר העלם דבר, מתוך שהוקשו זה לזה (ויקרא ד, כ)\u0005,\u0006","\u0003להכי איצטריך\u0004 \u0005[משום כך הוצרך]\u0006 לחזור ולכתוב בפר כהן משיח \u0003\"כאשר יורם\", דניהוי כמאן דכתב בגופיה\u0004 \u0005[שיהא\u0006 זה \u0005כמו\u0006 דבר \u0005שכתוב ב\u0006פר העלם דבר \u0005גופו],\u0006 \u0003ולא ניהוי\u0004 \u0005[יהא\u0006 זה\u0005]\u0006 \u0003דבר הלמד בהיקש חוזר ומלמד בהיקש.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: וליכתביה בגופיה ולא נקיש\u0004 \u0005[ושיכתוב בגופו\u0006 של פר העלם דבר \"כאשר יורם\", \u0005ולא\u0006 יצטרכו \u0005להיקש]!\u0006","ומשיבים: \u0003אי כתב בגופיה ולא אקיש\u0004 \u0005[אם היה כותב בו עצמו ולא היה מקיש],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 בכלל, \u0003דבר הלמד בהיקש חוזר ומלמד בהיקש. וכי תימא נקשי אקושי\u0004 \u0005[ואם היית אומר:\u0006 אם כן, \u0005נקיש אותו]\u0006 לפר כהן משיח, ומדוע \u0005צריך לכתוב בו דין זה? ניתן היה להשיב:\u0006 \u0003ניחא ליה דכתביה בגופיה מדאקיש ליה אקושי\u0004 \u0005[נוח לו לכתוב אותו בגופו מלהקיש אותו],\u0006 \u0003להכי כתביה ואקשיה\u0004 \u0005[משום כך כתב אותו וגם הקיש אותו],\u0006 \u0003למימרא\u0004 \u0005[לומר]\u0006 ללמוד מכאן ש\u0003דבר הלמד בהיקש אין חוזר ומלמד בהיקש.\u0004 כיון שעסקנו בענין שדבר הלמד בהיקש אינו חוזר ומלמד בהיקש, דנים בגמרא באפשרויות דומות של שימוש במידות של מדרש ההלכה בענייני קדשים. וסימנן: היק\"ש וגזיר\"ה שו\"ה ק\"ל וחומ\"ר, סימן. ואומרים תחילה: \u0003דבר הלמד בהיקש אין חוזר ומלמד מהיקש\u0004 — \u0003אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבא, אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבינא\u0004 בדיון הקודם. \u0003דבר הלמד בהיקש מהו שילמד בגזירה שוה?\u0004","","","ואומרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003ר' נתן בן אבטולמוס אומר: מנין לפריחה בבגדים\u0004 שאם פרחה צרעת בכל הבגד כולו \u0003שהיא טהורה? נאמר קרחת וגבחת בבגדים\u0004 (ויקרא יג, נה), \u0003ונאמר קרחת וגבחת באדם\u0004 (ויקרא יג, מב),","\u0003מה להלן\u0004 באדם אם \u0003פרח בכולו טהור\u0004 (ויקרא יג, יב) — \u0003אף כאן\u0004 בבגדים \u0003פרח בכולו טהור.\u0004","ושואלים: \u0003והתם מנא לן\u0004 \u0005[ושם מנין לנו]?\u0006 שהרי קרחת וגבחת נאמרה בנגעי הראש, ושם לא נאמר שהפריחה בכולו טהורה, אלא דווקא בנגעי הגוף! ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וכסתה הצרעת את כל עור הנגע \u0003מראשו ועד רגליו\"\u0004 (ויקרא יג, יב), \u0003ואיתקש\u0004 \u0005[והוקש]\u0006 בפסוק זה \u0003ראשו לרגל\u0004 (כלומר, נגעי הראש לנגעי הגוף), \u0003מה להלן\u0004 בנגעי גופו \u0003כולו הפך לבן פרח בכולו\u0004 — \u0003טהור, אף כאן\u0004 בראשו \u0003כולו הפך לבן פרח בכולו\u0004 — \u0003טהור.\u0004 ונמצא איפוא שלמדים גזירה שווה לנגעי בגדים מנגעי הראש, כאשר הם עצמם נלמדו בהיקש.","\u0003אמר ר' יוחנן:\u0004 אין מכאן ראיה לענייננו, כי \u0003בכל התורה כולה,\u0004 ובכלל זה בדיני צרעת, \u0003למידין למד מלמד, חוץ מן הקדשים, שאין דנין\u0004 בהם \u0003למד מלמד,\u0004 \u0003שאם כן\u0004 היינו למדים, \u0003לא יאמר צפונה\u0004 שחיטה בצפון \u0003באשם,\u0004 כפי שלמדנו מן ההיקש המפורש לעולה וחטאת (ראה לעיל בעמוד זה), \u0003ותיתי\u0004 \u0005[ושיילמד]\u0006 הדבר \u0003בגזירה שוה\u0004 של \u0003\"קדשי קדשים\" מחטאות,\u0004 שבשניהם נאמר \"קדש קדשים\" (ויקרא ו, יח. ויקרא ז, א),","","\u0003לאו למימרא\u0004 \u0005[האם אין לאמר מכאן]\u0006 ש\u0003דבר הלמד בהיקש אין חוזר ומלמד בגזירה שוה?\u0004 שהרי חטאת עצמה נלמדת בהיקש מעולה.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אין למדים בגזירה שווה זו מחטאת לאשם בגלל סיבה אחרת, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 את הגזירה השווה ולומר: \u0003מה לחטאת\u0004 שהיא חמורה \u0003שכן מכפרת על חייבי כריתות!\u0004","ומשיבים: לא ניתן היה לפרוך גזירה שווה זו מעצמה, כי \u0003קדשי קדשים יתירי כתיבי\u0004 \u0005[מיותרים כתובים],\u0006 ובמקרה כזה לא ניתן לפרוך גזירה שווה. ולפיכך, מה שאין למדים מחטאת לאשם בגזירה שווה אינו אלא משום שהיא נלמדה בהיקש.","וממשיכים לדון בצירופי מידות. ותחילה אומרים: \u0003דבר הלמד מהיקש חוזר ומלמד בקל וחומר,\u0004"]]};
